window.MIT_COURSE_PARTS=window.MIT_COURSE_PARTS||[];window.MIT_COURSE_PARTS.push([{"code":"2.723B","title":"Design Thinking and Innovation Project","level":"U","description":"Project-based subject. Students employ design-thinking techniques learned in 6.902A to develop a robust speech-recognition application using a web-based platform. Students practice in leadership and teamwork skills as they collaboratively conceive, implement, and iteratively refine their designs based on user feedback. Topics covered include techniques for leading the creative process in teams, the ethics of engineering systems, methods for articulating designs with group collaboration, identifying and reconciling paradoxes of engineering designs, and communicating solution concepts with impact. Students present oral presentations and receive feedback to sharpen their communication skills.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"},{"days":["M"],"start":"15:00","end":"17:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.723B"},{"code":"2.729","title":"D-Lab: Design for Scale","level":"U","description":"Explores the external factors affecting product development for people in low-resource settings in a project-based context. Students apply existing engineering skills in interdisciplinary teams to identify contextual limitations and develop previously established prototypes towards manufacturing-ready product designs for real-world project sponsors. Topics are presented within the context of the developing world and include technology feasibility and scalability assessment; value chain analysis; product specification; and manufacturing methodologies at various scales. Lessons are experiential and case study-based, taught by instructors with field experience and industry experts from product development consulting firms and the consumer electronics industry. Students taking graduate version complete additional written assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:00","end":"15:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.729"},{"code":"2.733","title":"Engineering Systems Design","level":"G","description":"Focuses on the design of engineering systems to satisfy stated performance, stability, and/or control requirements. Emphasizes individual initiative, application of fundamental principles, and the compromises inherent in the engineering design process. Culminates in the design of an engineering system, typically a vehicle or other complex system. Includes instruction and practice in written and oral communication through team presentation, design reviews, and written reports. Students taking graduate version complete additional assignments. Enrollment may be limited due to laboratory capacity.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"17:00","room":"NE45-202A"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.733"},{"code":"2.737","title":"Mechatronics","level":"G","description":"Introduction to designing mechatronic systems, which require integration of the mechanical and electrical engineering disciplines within a unified framework. Significant laboratory-based design experiences form subject's core. Final project. Topics include: low-level interfacing of software with hardware; use of high-level graphical programming tools to implement real-time computation tasks; digital logic; analog interfacing and power amplifiers; measurement and sensing; electromagnetic and optical transducers; control of mechatronic systems. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"1-135"}]},{"type":"Lab","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"1-004"},{"days":["R"],"start":"14:00","end":"17:00","room":"1-004"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.737"},{"code":"2.77","title":"FUNdaMENTALS of Precision Product Design","level":"G","description":"Examines design, selection, and combination of machine elements to produce a robust precision system. Introduces process, philosophy and physics-based principles of design to improve/enable renewable power generation, energy efficiency, and manufacturing productivity. Topics include linkages, power transmission, screws and gears, actuators, structures, joints, bearings, error apportionment, and error budgeting. Considers each topic with respect to its physics of operation, mechanics (strength, deformation, thermal effects) and accuracy, repeatability, and resolution. Includes guest lectures from practicing industry and academic leaders.  Students design, build, and test a small benchtop precision machine, such as a heliostat for positioning solar PV panels or a two or three axis machine.  Prior to each lecture, students review the pre-recorded detailed topic materials and then converge on what parts of the topic they want covered in extra depth in lecture.  Students are assessed on their preparation for and participation in class sessions. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"3-442"}]},{"type":"Lab","options":[{"days":["T"],"start":"12:30","end":"15:30","room":"3-442"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.77"},{"code":"2.772","title":"Thermodynamics of Biomolecular Systems","level":"U","description":"Equilibrium properties of macroscopic and microscopic systems. Basic thermodynamics: state of a system, state variables. Work, heat, first law of thermodynamics, thermochemistry. Second and third law of thermodynamics: entropy and its statistical basis, Gibbs function. Chemical equilibrium of reactions in gas and solution phase. Macromolecular structure and interactions in solution. Driving forces for molecular self-assembly. Binding cooperativity, solvation, titration of macromolecules.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"3-270"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"16:00","end":"17:00","room":"1-242"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"1-242"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"1-277"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-277"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.772"},{"code":"2.777","title":"Systems Thinking and Complex Problem Solving","level":"U","description":"Provides instruction in both principle-based and experience-based approaches to systems architecting. For the former, students use design principles to develop concepts for large and complex systems; for the latter, heuristic-based insights and problem-solving strategies are applied to large and complex national defense systems. Interactive lectures and in-class projects guide participants in addressing and solving unfamiliar large and complex problems. Students taking graduate version complete projects individually; students taking undergraduate version work in groups.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"5-234"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.777"},{"code":"2.778","title":"Systems Thinking and Complex Problem Solving","level":"G","description":"Provides instruction in both principle-based and experience-based approaches to systems architecting. For the former, students use design principles to develop concepts for large and complex systems; for the latter, heuristic-based insights and problem-solving strategies are applied to large and complex national defense systems. Interactive lectures and in-class projects guide participants in addressing and solving unfamiliar large and complex problems. Students taking graduate version complete projects individually; students taking undergraduate version work in groups. Limited enrollment.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"5-234"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.778"},{"code":"2.787","title":"Tissue Engineering and Organ Regeneration","level":"G","description":"Principles and practice of tissue engineering (TE) and organ regeneration (OR). Topics include: cellular/molecular processes that induce fibrosis following traumatic injury, surgical excision, disease, and aging; targets for treatment for induced regeneration; and the tools that can be used to formulate the treatments. Presents the basic science of organ regeneration. Principles underlying engineering strategies for employing select implantable or injectable biomaterial scaffolds, exogenous cells or their organelles, and drugs or regulatory molecules, for the formation of tissue in vitro (TE) and regeneration of tissues/organs in vivo (OR). Describes the technologies for producing biomaterial scaffolds and for incorporating cells and regulatory molecules into workable devices. Examples of clinical successes and failures of regenerative devices are analyzed as case studies.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.787"},{"code":"2.788","title":"Mechanical Engineering and Design of Living Systems","level":"G","description":"For students interested in research at the interface of mechanical engineering, biology, and materials science. Specific emphasis lies on interfacing living systems with engineered materials and devices, and on engineering living system behavior.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-371"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.788"},{"code":"2.789","title":"D-Lab: Design for Scale","level":"G","description":"Explores the external factors affecting product development for people in low-resource settings in a project-based context. Students apply existing engineering skills in interdisciplinary teams to identify contextual limitations and develop previously established prototypes towards manufacturing-ready product designs for real-world project sponsors. Topics are presented within the context of the developing world and include technology feasibility and scalability assessment; value chain analysis; product specification; and manufacturing methodologies at various scales. Lessons are experiential and case study-based, taught by instructors with field experience and industry experts from product development consulting firms and the consumer electronics industry. Students taking graduate version complete additional written assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:00","end":"15:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.789"},{"code":"2.792","title":"Quantitative and Clinical Physiology","level":"U","description":"Application of the principles of energy and mass flow to major human organ systems. Anatomical, physiological and clinical features of the cardiovascular, respiratory and renal systems. Mechanisms of regulation and homeostasis. Systems, features and devices that are most illuminated by the methods of physical sciences and engineering models. Required laboratory work includes animal studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-265"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["W"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.792"},{"code":"2.795","title":"Fields, Forces, and Flows in Biological Systems","level":"G","description":"Molecular diffusion, diffusion-reaction, conduction, convection in biological systems; fields in heterogeneous media; electrical double layers; Maxwell stress tensor, electrical forces in physiological systems. Fluid and solid continua: equations of motion useful for porous, hydrated biological tissues. Case studies of membrane transport, electrode interfaces, electrical, mechanical, and chemical transduction in tissues, convective-diffusion/reaction, electrophoretic, electroosmotic flows in tissues/MEMs, and ECG. Electromechanical and physicochemical interactions in cells and biomaterials; musculoskeletal, cardiovascular, and other biological and clinical examples. Prior undergraduate coursework in transport recommended.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.795"},{"code":"2.796","title":"Quantitative and Clinical Physiology","level":"G","description":"Application of the principles of energy and mass flow to major human organ systems. Anatomical, physiological and clinical features of the cardiovascular, respiratory and renal systems. Mechanisms of regulation and homeostasis. Systems, features and devices that are most illuminated by the methods of physical sciences and engineering models. Required laboratory work includes animal studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-265"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["W"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.796"},{"code":"2.810","title":"Manufacturing Processes and Systems","level":"G","description":"Introduction to manufacturing processes and manufacturing systems including assembly, machining, injection molding, casting, thermoforming, and more. Emphasis on the physics and randomness and how they influence quality, rate, cost, and flexibility. Attention to the relationship between the process and the system, and the process and part design. Project (in small groups) requires fabrication (and some design) of a product using several different processes (as listed above). Enrollment may be limited due to laboratory constraints; preference given to MechE students and students who need to satisfy degree requirements.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"37-212"}]},{"type":"Lab","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"35-125"},{"days":["T"],"start":"14:00","end":"17:00","room":"35-125"},{"days":["W"],"start":"09:00","end":"12:00","room":"35-125"},{"days":["R"],"start":"09:00","end":"12:00","room":"35-125"},{"days":["R"],"start":"14:00","end":"17:00","room":"35-125"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.810"},{"code":"2.830","title":"Control of Manufacturing Processes","level":"G","description":"Statistical modeling and control in manufacturing processes. Use of experimental design and response surface modeling to understand manufacturing process physics. Defect and parametric yield modeling and optimization. Forms of process control, including statistical process control, run by run and adaptive control, and real-time feedback control. Application contexts include semiconductor manufacturing, conventional metal and polymer processing, and emerging micro-nano manufacturing processes.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.830"},{"code":"2.853","title":"Introduction to Manufacturing Systems","level":"U","description":"Provides ways to analyze manufacturing systems in terms of material flow and storage, information flow, capacities, and times and durations of events. Fundamental topics include probability, inventory and queuing models, forecasting, optimization, process analysis, and linear and dynamic systems. Factory planning and scheduling topics include flow planning, bottleneck characterization, buffer and batch-size tactics, seasonal planning, and dynamic behavior of production systems. Graduate students are required to complete additional assignments with stronger analytical content.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"3-133"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.853"},{"code":"2.854","title":"Introduction to Manufacturing Systems","level":"G","description":"Provides ways to analyze manufacturing systems in terms of material flow and storage, information flow, capacities, and times and durations of events. Fundamental topics include probability, inventory and queuing models, forecasting, optimization, process analysis, and linear and dynamic systems. Factory planning and scheduling topics include flow planning, bottleneck characterization, buffer and batch-size tactics, seasonal planning, and dynamic behavior of production systems. Graduate students are required to complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"3-133"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.854"},{"code":"2.874","title":"Process Data Analytics","level":"U","description":"Provides an introduction to data analytics for manufacturing processes. Topics include chemometrics, discriminant analysis, hyperspectral imaging, machine learning, big data, Bayesian methods, experimental design, feature spaces, and pattern recognition as relevant to manufacturing process applications (e.g., output estimation, process control, and fault detection, identification and diagnosis). Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.874"},{"code":"2.884","title":"Process Data Analytics","level":"G","description":"Provides an introduction to data analytics for manufacturing processes. Topics include chemometrics, discriminant analysis, hyperspectral imaging, machine learning, big data, Bayesian methods, experimental design, feature spaces, and pattern recognition as relevant to manufacturing process applications (e.g., output estimation, process control, and fault detection, identification and diagnosis). Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.884"},{"code":"2.890","title":"Global Operations Leadership Seminar","level":"G","description":"Integrative forum in which worldwide leaders in business, finance, government, sports, and education share their experiences and insights with students aspiring to run global operations. Students play a large role in managing the seminar. Preference to LGO students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.890"},{"code":"2.900","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies alongside key readings by foundational ethical thinkers from Aristotle to Martin Luther King, Jr., and investigate which ethical approaches are best and how to apply them. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based, with the aim of introducing students to new ways of thinking. All sections cover the same core ethical frameworks, but some sections have a particular focus for case studies, such as bioengineering, or have an in-depth emphasis on particular thinkers. The subject is taught in separate sections. Students are eligible to take any section regardless of their registered subject number. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"},{"days":["R"],"start":"15:00","end":"17:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.900"},{"code":"2.907","title":"Innovation Teams","level":"G","description":"Introduces skills and capabilities for real-world problem solving to take technology from lab to societal impact: technical and functional exploration, opportunity discovery, market understanding, value economics, scale-up, intellectual property, and communicating/working for impact across disciplines. Students work in multidisciplinary teams formed around MIT research breakthroughs, with extensive in-class coaching and guidance from faculty, lab members, and select mentors. Follows a structured approach to innovating in which everything is a variable and the product, technology, and opportunities for new ventures can be seen as an act of synthesis. Teams gather evidence that permits a fact-based iteration across multiple application domains, markets, functionalities, technologies, and products, leading to a recommendation that maps a space of opportunity and includes actionable next steps to evolve the market and technology.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"15:00","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.907"},{"code":"2.96","title":"Management in Engineering","level":"U","description":"Introduction and overview of engineering management. Financial principles, management of innovation, technical strategy and best management practices. Case study method of instruction emphasizes participation in class discussion. Focus is on the development of individual skills and management tools. Restricted to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"1-150"},{"days":["T"],"start":"10:00","end":"11:00","room":"1-375"},{"days":["R"],"start":"16:00","end":"17:00","room":"1-375"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.96"},{"code":"2.961","title":"Management in Engineering","level":"G","description":"Introduction and overview of engineering management. Financial principles, management of innovation, technical strategy and best management practices. Case study method of instruction emphasizes participation in class discussion. Focus is on the development of individual skills and management tools.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"35-308"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.961"},{"code":"2.991","title":"Introduction to Graduate Study in Mechanical Engineering","level":"G","description":"Familiarizes students with the requirements for their desired degree and the resources, both at MIT and beyond, to help them reach their educational and professional goals. Series of interactive lectures and seminars guides students through various aspects of life critical to navigating graduate school successfully. Topics include course requirements, PhD qualifying examinations, advisor/advisee relationships, funding and fellowships, mental health and wellbeing, housing options in the Boston area, and career options after graduation. Limited to first-year graduate students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.991"},{"code":"2.C27","title":"Computational Imaging: Physics and Algorithms","level":"U","description":"Explores the contemporary computational understanding of imaging: encoding information about a physical object onto a form of radiation, transferring the radiation through an imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. Introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds describe the physical and algorithmic parts in two exemplary imaging systems. The third round involves a class project on an imaging system chosen by students. Undergraduate and graduate versions share lectures but have different recitations. Involves optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.C27"},{"code":"2.C67","title":"Computational Imaging: Physics and Algorithms","level":"G","description":"Contemporary understanding of imaging is computational: encoding onto a form of radiation the information about a physical object, transferring the radiation through the imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. This class introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds, instructors describe the physical and algorithmic parts in two exemplary imaging systems. The third round, students conduct themselves as the class project on an imaging system of their choice. The undergraduate and graduate versions share lectures but have different recitations. Throughout the term, we also conduct optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.C67"},{"code":"2.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.EPE"},{"code":"2.S795","title":"Graduate Special Subject in Mechanical Engineering","level":"G","description":"Lecture, seminar or laboratory course consisting of material not offered in regularly scheduled subjects. Can be repeated for credit only for completely different subject matter.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.S795"},{"code":"2.S973","title":"Undergraduate Special Subject in Mechanical Engineering","level":"U","description":"Lecture, seminar or laboratory course consisting of material not offered in regularly scheduled subjects. Can be repeated for credit only for completely different subject matter. 2.S972-2.S974 are graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.S973"},{"code":"2.S974","title":"Undergraduate Special Subject in Mechanical Engineering","level":"U","description":"Lecture, seminar or laboratory course consisting of material not offered in regularly scheduled subjects. Can be repeated for credit only for completely different subject matter.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"16:30","room":"36-112"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:30","end":"12:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.S974"},{"code":"2.S986","title":"Special Subject in Mechanical Engineering","level":"G","description":"Lecture, seminar, or laboratory consisting of material not offered in regularly scheduled subjects. Can be repeated for credit only for completely different subject matter.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.S986"},{"code":"2.S998","title":"Graduate Special Subject in Mechanical Engineering","level":"G","description":"Advanced lecture, seminar, or laboratory consisting of material not offered in regularly scheduled subjects. Can be repeated for credit only for completely different subject matter.  2.S980 and 2.S996 are graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"16:30","room":"36-112"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:30","end":"12:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.S998"},{"code":"2.UAR","title":"Seminar in Undergraduate Advanced Research","level":"U","description":"Instruction in effective undergraduate research, including choosing and developing a research topic, surveying previous work and publications, research topics in EECS and the School of Engineering, industry best practices, design for robustness, technical presentation, authorship and collaboration, and ethics. Students engage in extensive written and oral communication exercises, in the context of an approved advanced research project. A total of 12 units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult EECS SuperUROP website for more information.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m2c.html#2.UAR"},{"code":"20.001","title":"Introduction to Professional Success and Leadership in Biological Engineering","level":"U","description":"Interactive introduction to the discipline of Biological Engineering through presentations by alumni practitioners, with additional panels and discussions on skills for professional development. Presentations emphasize the roles of communication through writing and speaking, building and maintaining professional networks, and interpersonal and leadership skills in building successful careers. Provides practical advice about how to prepare for job searches and graduate or professional school applications from an informed viewpoint. Prepares students for UROPs, internships, and selection of BE electives. Subject can count toward the 6-unit discovery-focused credit limit for first-year students.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"10:00","room":"3-270"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.001"},{"code":"20.005","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies along with foundational ethical readings, and investigate which ethical approaches are best and how to apply them as engineers. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based. All sections cover the same core ethical frameworks, but some sections have a particular focus for engineering case studies, such as Computer Science or Bioengineering. Students are eligible to take any section of the course, regardless of their registered course number. The subject is taught in separate sections. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"},{"days":["R"],"start":"15:00","end":"17:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.005"},{"code":"20.010","title":"Introduction to Experimentation in BE","level":"U","description":"Teaches students to ask research questions and use the steps in the experimental method to test hypotheses. Introduces best practices in basic data analysis and interpretation. Additional topics include exploring experimental failures, unexpected results, and troubleshooting. Goal is to prepare students for undergraduate research opportunities and laboratory-based coursework. This is a discussion-based subject and is dependent on group participation. Preference to first- and second-year students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.010"},{"code":"20.051","title":"Introduction to NEET: Living Machines","level":"U","description":"Focuses on physiomimetics: transforming therapeutic strategy and development. Overview of development of therapies for complex diseases, including disease mechanisms in heterogeneous patient populations, developing therapeutic strategies, modeling these in vitro, and testing the therapies. Explores the five essential technological contributions to this process: computational systems biology, synthetic biology, immuno-engineering, microphysiological systems devices/tissue engineering, and microfluidic device engineering for in vitro models and analysis. Introduces disease modeling, patient stratification, and drug development processes, includes extensive examples from industry, and provides context for choosing a concentration track in the Living Machines thread. Weekly lectures from experts in the field supplemented with structured, short projects in each topic area. Limited to 24; preference to students in the NEET Living Machines thread.","groups":[{"type":"Lecture","options":[{"days":["W","F"],"start":"16:00","end":"17:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.051"},{"code":"20.054","title":"NEET - Living Machines Research Immersion","level":"U","description":"A structured lab research experience in a specific Living Machines track. Students identify a project in a participating research lab, on a topic related to the five tracks in the NEET Living Machines program, propose a project related to the drug development theme, and prepare interim and final presentations and reports while conducting the project. Links to industry-sponsored research projects at MIT are encouraged. Project proposal must be submitted and approved in the term prior to enrollment. Limited to students in the NEET Living Machines thread.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.054"},{"code":"20.106","title":"Applied Microbiology","level":"U","description":"Introductory microbiology from a systems perspective - considers microbial diversity and the integration of data from a molecular, cellular, organismal, and ecological context to understand the interaction of microbial organisms with their environment. Special emphasis on specific viral, bacterial, and eukaryotic microorganisms and their interaction with animal hosts with focus on contemporary problems in areas such as vaccination, emerging disease, antimicrobial drug resistance, and toxicology.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"26-168"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.106"},{"code":"20.109","title":"Laboratory Fundamentals in Biological Engineering","level":"U","description":"Introduces experimental biochemical and molecular techniques from a quantitative engineering perspective. Experimental design, data analysis, and scientific communication form the underpinnings of this subject. In this, students complete discovery-based experimental modules drawn from current technologies and active research projects of BE faculty. Generally, topics include DNA engineering, in which students design, construct, and use genetic material; parts engineering, emphasizing protein design and quantitative assessment of protein performance; systems engineering, which considers genome-wide consequences of genetic perturbations; and biomaterials engineering, in which students use biologically-encoded devices to design and build materials. Enrollment limited; priority to Course 20 majors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"16-220"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"13:00","end":"17:00","room":"56-322"},{"days":["W","F"],"start":"13:00","end":"17:00","room":"56-322"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.109"},{"code":"20.110","title":"Thermodynamics of Biomolecular Systems","level":"U","description":"Equilibrium properties of macroscopic and microscopic systems. Basic thermodynamics: state of a system, state variables. Work, heat, first law of thermodynamics, thermochemistry. Second and third law of thermodynamics: entropy and its statistical basis, Gibbs function. Chemical equilibrium of reactions in gas and solution phase. Macromolecular structure and interactions in solution. Driving forces for molecular self-assembly. Binding cooperativity, solvation, titration of macromolecules.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"3-270"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"16:00","end":"17:00","room":"1-242"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"1-242"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"1-277"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-277"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.110"},{"code":"20.200","title":"Biological Engineering Seminar","level":"G","description":"Weekly one-hour seminars covering graduate student research and presentations by invited speakers.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.200"},{"code":"20.201","title":"Fundamentals of Drug Development","level":"G","description":"Team-based exploration of the scientific basis for developing new drugs. First portion of term covers fundamentals of target identification, drug discovery, pharmacokinetics, pharmacodynamics, regulatory policy, and intellectual property. Industry experts and academic entrepreneurs then present case studies of specific drugs, drug classes, and therapeutic targets. In a term-long project, student teams develop novel therapeutics to solve major unmet medical needs, with a trajectory to a 'start-up' company. Culminates with team presentations to a panel of industry and scientific leaders.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"56-614"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:30","end":"14:30","room":"56-614"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.201"},{"code":"20.305","title":"Principles of Synthetic Biology","level":"U","description":"Introduces the basics of synthetic biology, including quantitative cellular network characterization and modeling. Considers the discovery and genetic factoring of useful cellular activities into reusable functions for design. Emphasizes the principles of biomolecular system design and diagnosis of designed systems. Illustrates cutting-edge applications in synthetic biology and enhances skills in analysis and design of synthetic biological applications. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.305"},{"code":"20.309","title":"Instrumentation and Measurement for Biological Systems","level":"U","description":"Explores the intricate relationship between measuring, manipulating, and modeling biological systems. Lectures cover the application of engineering techniques — such as statistics, signal processing, system identification, and control theory — to biological systems. Lab sessions focus on optical methods and electronics. Fundamental topics include measurement error and the limits of precision and accuracy. Students taking graduate version complete additional assignments. Enrollment limited; preference to Course 20 undergraduates.","groups":[{"type":"Lecture","options":[{"days":["T","R","F"],"start":"12:00","end":"13:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.309"},{"code":"20.320","title":"Analysis of Biomolecular and Cellular Systems","level":"U","description":"Analysis of molecular and cellular processes across a hierarchy of scales, including genetic, molecular, cellular, and cell population levels. Topics include gene sequence analysis, molecular modeling, metabolic and gene regulation networks, signal transduction pathways and cell populations in tissues. Emphasis on experimental methods, quantitative analysis, and computational modeling.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"32-155"}]},{"type":"Recitation","options":[{"days":["M"],"start":"15:00","end":"16:00","room":"56-114"},{"days":["F"],"start":"10:00","end":"11:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.320"},{"code":"20.335","title":"Multiphysics Systems Modeling","level":"U","description":"Practices the use of modern numerical analysis tools (e.g., COMSOL) for biological and other systems with multi-physics behavior. Covers modeling diffusion, reaction, convection, and other transport mechanisms. Analysis of microfluidic devices provided as examples. Discusses practical issues and challenges in numerical modeling. Includes weekly modeling homework and major modeling projects. No prior knowledge of modeling software is required. Lectures are viewed outside of class; in-class time is dedicated to problem-solving and discussion. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.335"},{"code":"20.352","title":"Principles of Neuroengineering","level":"U","description":"Covers how to innovate technologies for brain analysis and engineering, for accelerating the basic understanding of the brain, and leading to new therapeutic insight and inventions. Focuses on using physical, chemical and biological principles to understand technology design criteria governing ability to observe and alter brain structure and function. Topics include optogenetics, noninvasive brain imaging and stimulation, nanotechnologies, stem cells and tissue engineering, and advanced molecular and structural imaging technologies. Includes design projects.  Students taking graduate version complete additional assignments. Designed for students with engineering maturity who are ready for design.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"46-5165"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.352"},{"code":"20.371","title":"Biological and Engineering Principles Underlying Novel Biotherapeutics","level":"U","description":"Covers biological and bioengineering principles underlying the development and therapeutic use of recombinant proteins and immune cells. Special attention to monoclonal antibodies and engineered immune system cells as therapeutics; protein- and glyco- engineering to enhance protein function; protein pharmacology and delivery; nucleic acid- based biotherapeutics; generation of functional cells and tissues from embryonic stem cells and iPS cells; and immune cell-cancer cell interactions in cancer immunotherapy.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"17:00","room":""}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.371"},{"code":"20.380","title":"Biological Engineering Design","level":"U","description":"Illustrates how knowledge and principles of biology, biochemistry, and engineering are integrated to create new products for societal benefit. Uses case study format to examine recently developed products of pharmaceutical and biotechnology industries: how a product evolves from initial idea, through patents, testing, evaluation, production, and marketing. Emphasizes scientific and engineering principles, as well as the responsibility scientists, engineers, and business executives have for the consequences of their technology. Instruction and practice in written and oral communication provided. Enrollment limited; preference to Course 20 undergraduates.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"12:00","room":"56-614"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.380"},{"code":"20.382","title":"Research in the World","level":"U","description":"Focuses on refining, reframing, and translating students' existing projects to provide an opportunity for them to explore the real-world applications of their research. Students bring an active research project (for example, a senior thesis, SuperUROP, or clinical collaboration) and class materials teach them to see it differently: through the lens of audience, design constraint, policy and cultural context, and real-world translation. Instruction combines lectures, workshops with external practitioners, and structured peer critique. Instruction focuses on refining, reframing, and translating work that already exists, equipping students with the analytical and communicative tools to move their research from the laboratory into the world. Provides instruction and practice in written and oral communication. Priority to Course 20 students; open to other departments with instructor permission. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.382"},{"code":"20.389","title":"The Bioeconomy and Society","level":"U","description":"Characterizes and examines the transformation of the production of fuels, foods, materials, and medicines through sustainable processes based on bacteria, fungi, algae, and plants, to inaugurate a biologically-based economy, or 'bioeconomy.' Studies this developing bioeconomy and its antecedent political, technological, and cultural events, as well as its potential social impacts. Includes guest speakers from policy, industry, and academia. Discusses the scientific research which offers outside perspectives on opportunities and challenges that the bioeconomy presents. Students work in project-based teams throughout the term to analyze the historical and contemporary dimensions of one feature of the bioeconomy.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-139"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.389"},{"code":"20.405","title":"Principles of Synthetic Biology","level":"G","description":"Introduces the basics of synthetic biology, including quantitative cellular network characterization and modeling. Considers the discovery and genetic factoring of useful cellular activities into reusable functions for design. Emphasizes the principles of biomolecular system design and diagnosis of designed systems. Illustrates cutting-edge applications in synthetic biology and enhances skills in analysis and design of synthetic biological applications. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.405"},{"code":"20.409","title":"Instrumentation and Measurement for Biological Systems","level":"G","description":"Explores the intricate relationship between measuring, manipulating, and modeling biological systems. Lectures cover the application of engineering techniques — such as statistics, signal processing, system identification, and control theory — to biological systems. Lab sessions focus on optical methods and electronics. Fundamental topics include measurement error and the limits of precision and accuracy. Students taking graduate version complete additional assignments. Limited to five graduate students.","groups":[{"type":"Lecture","options":[{"days":["T","R","F"],"start":"12:00","end":"13:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.409"},{"code":"20.420","title":"Principles of Molecular Bioengineering","level":"G","description":"Provides an introduction to the mechanistic analysis and engineering of biomolecules and biomolecular systems. Covers methods for measuring, modeling, and manipulating systems, including biophysical experimental tools, computational modeling approaches, and molecular design. Equips students to take systematic and quantitative approaches to the investigation of a wide variety of biological phenomena.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.420"},{"code":"20.430","title":"Fields, Forces, and Flows in Biological Systems","level":"G","description":"Molecular diffusion, diffusion-reaction, conduction, convection in biological systems; fields in heterogeneous media; electrical double layers; Maxwell stress tensor, electrical forces in physiological systems. Fluid and solid continua: equations of motion useful for porous, hydrated biological tissues. Case studies of membrane transport, electrode interfaces, electrical, mechanical, and chemical transduction in tissues, convective-diffusion/reaction, electrophoretic, electroosmotic flows in tissues/MEMs, and ECG. Electromechanical and physicochemical interactions in cells and biomaterials; musculoskeletal, cardiovascular, and other biological and clinical examples. Prior undergraduate coursework in transport recommended.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.430"},{"code":"20.435","title":"Multiphysics Systems Modeling","level":"G","description":"Practices the use of modern numerical analysis tools (e.g., COMSOL) for biological and other systems with multi-physics behavior. Covers modeling diffusion, reaction, convection, and other transport mechanisms. Analysis of microfluidic devices provided as examples. Discusses practical issues and challenges in numerical modeling. Includes weekly modeling homework and major modeling projects. No prior knowledge of modeling software is required. Lectures are viewed outside of class; in-class time is dedicated to problem-solving and discussion. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.435"},{"code":"20.445","title":"Methods and Problems in Microbiology","level":"G","description":"Students will read and discuss primary literature covering key areas of microbial research with emphasis on methods and approaches used to understand and manipulate microbes. Preference to first-year Microbiology and Biology students.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"15:30","room":"68-156"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.445"},{"code":"20.446","title":"Microbial Genetics and Evolution","level":"G","description":"Covers aspects of microbial genetic and genomic analyses, central dogma, horizontal gene transfer, and evolution.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:30","room":"66-160"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.446"},{"code":"20.450","title":"Applied Microbiology","level":"G","description":"Compares the complex molecular and cellular interactions in health and disease between commensal microbial communities, pathogens and the human or animal host. Special focus is given to current research on microbe/host interactions, infection of significant importance to public health, and chronic infectious disease. Classwork will include lecture, but emphasize critical evaluation and class discussion of recent scientific papers, and the development of new research agendas in the fields presented.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"26-168"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.450"},{"code":"20.452","title":"Principles of Neuroengineering","level":"G","description":"Covers how to innovate technologies for brain analysis and engineering, for accelerating the basic understanding of the brain, and leading to new therapeutic insight and inventions. Focuses on using physical, chemical and biological principles to understand technology design criteria governing ability to observe and alter brain structure and function. Topics include optogenetics, noninvasive brain imaging and stimulation, nanotechnologies, stem cells and tissue engineering, and advanced molecular and structural imaging technologies. Includes design projects. Designed for students with engineering maturity who are ready for design. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"46-5165"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.452"},{"code":"20.454","title":"Revolutionary Ventures: How to Invent and Deploy Transformative Technologies","level":"G","description":"Seminar on envisioning and building ideas and organizations to accelerate engineering revolutions. Focuses on emerging technology domains, such as neurotechnology, imaging, cryotechnology, gerontechnology, and bio-and-nano fabrication. Draws on historical examples as well as live case studies of existing or emerging organizations, including labs, institutes, startups, and companies. Goals range from accelerating basic science to developing transformative products or therapeutics. Each class is devoted to a specific area, often with invited speakers, exploring issues from the deeply technical through the strategic. Individually or in small groups, students prototype new ventures aimed at inventing and deploying revolutionary technologies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"16:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.454"},{"code":"20.507","title":"Introduction to Biological Chemistry","level":"U","description":"Chemical and physical properties of the cell and its building blocks. Structures of proteins and principles of catalysis. The chemistry of organic/inorganic cofactors required for chemical transformations within the cell. Basic principles of metabolism and regulation in pathways, including glycolysis, gluconeogenesis, fatty acid synthesis/degradation, pentose phosphate pathway, Krebs cycle and oxidative phosphorylation, DNA replication, and transcription and translation.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:00","end":"10:00","room":"2-105"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"13:00","end":"14:00","room":"36-112"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"36-144"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.507"},{"code":"20.554","title":"Advances in Chemical Biology","level":"G","description":"Introduction to current research at the interface of chemistry, biology, and bioengineering. Topics include imaging of biological processes, metabolic pathway engineering, protein engineering, mechanisms of DNA damage, RNA structure and function, macromolecular machines, protein misfolding and disease, metabolomics, and methods for analyzing signaling network dynamics. Lectures are interspersed with class discussions and student presentations based on current literature.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.554"},{"code":"20.561","title":"Eukaryotic Cell Biology: Principles and Practice","level":"G","description":"Emphasizes methods and logic used to analyze structure and function of eukaryotic cells in diverse systems (e.g., yeast, fly, worm, mouse, human; development, stem cells, neurons). Combines lectures and in-depth roundtable discussions of literature readings with the active participation of faculty experts. Focuses on membranes (structure, function, traffic), organelles, the cell surface, signal transduction, cytoskeleton, cell motility and extracellular matrix. Ranges from basic studies to applications to human disease, while stressing critical analysis of experimental approaches. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.561"},{"code":"20.930","title":"Research Experience in Biopharma","level":"G","description":"Provides exposure to industrial science and develops skills necessary for success in such an environment. Under the guidance of an industrial mentor, students participate in on-site research at a local biopharmaceutical company where they observe and participate in industrial science. Serves as a real-time case study to internalize the factors that shape R&D in industry, including the purpose and scope of a project, key decision points in the past and future, and strategies for execution. Students utilize company resources and work with a scientific team to contribute to the goals of their assigned project; they then present project results to the company and class, emphasizing the logic that dictated their work and their ideas for future directions. Lecture component focuses on professional development. Enrollment may be limited based on availability of internship opportunities. Open to MIT students only.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"11:00","end":"12:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.930"},{"code":"20.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.EPE"},{"code":"20.S900","title":"Special Subject in Biological Engineering","level":"U","description":"Detailed discussion of selected topics of current interest. Classwork in various areas not covered by regular subjects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-132"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.S900"},{"code":"20.S940","title":"Special Subject in Biological Engineering","level":"U","description":"Detailed discussion of selected topics of current interest. Classwork in various areas not covered by regular subjects.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.S940"},{"code":"20.S948","title":"Special Subject in Biological Engineering","level":"G","description":"Detailed discussion of selected topics of current interest. Classwork in various areas not covered by regular subjects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-132"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.S948"},{"code":"20.S952","title":"Special Subject in Biological Engineering","level":"G","description":"Detailed discussion of selected topics of current interest. Classwork in various areas not covered by regular subjects.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"18:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m20a.html#20.S952"},{"code":"21.01","title":"Compass Course: Moral and Social Questions about the Human Condition","level":"U","description":"Guides exploration of the persistent moral and social questions central to the human experience through active debate; multidisciplinary conversation; and collective engagement with historical and contemporary work in the humanities, arts, and social sciences. Seminar-style classes, diverse readings, simulation games, and faculty from across SHASS facilitate students grappling with questions of value, genius, merit, truth, justice, governance, and more. Class is focused on group discussion and experiential learning activities; video lectures are asynchronous. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"09:00","end":"11:00","room":"2-139"},{"days":["M"],"start":"19:00","end":"21:00","room":"2-139"},{"days":["T"],"start":"09:00","end":"11:00","room":"1-132"},{"days":["T"],"start":"11:00","end":"13:00","room":"48-308"},{"days":["T"],"start":"15:00","end":"17:00","room":"1-132"},{"days":["W"],"start":"13:00","end":"15:00","room":"E25-117"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"2-139"},{"days":["F"],"start":"09:00","end":"10:00","room":"2-139"},{"days":["R"],"start":"09:00","end":"10:00","room":"1-132"},{"days":["R"],"start":"11:00","end":"12:00","room":"48-308"},{"days":["F"],"start":"12:00","end":"13:00","room":"1-132"},{"days":["F"],"start":"13:00","end":"14:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m21a.html#21.01"},{"code":"21A.01","title":"How Culture Works","level":"U","description":"Introduces diverse meanings and uses of the concept of culture with historical and contemporary examples from scholarship and popular media around the globe. Includes first-hand observations, synthesized histories and ethnographies, quantitative representations, and visual and fictionalized accounts of human experiences. Students conduct empirical research  on cultural differences through the systematic observation of human interaction, employ methods of interpretative analysis, and practice convincing others of the accuracy of their findings.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.01"},{"code":"21A.103","title":"The Science of Race, Sex, and Gender","level":"U","description":"Examines the role of science and medicine in the origins and evolution of the concepts of race, sex, and gender from the 17th century to the present. Focus on how biological, anthropological, and medical concepts intersect with social, cultural, and political ideas about racial, sexual, and gender difference in the US and globally. Approach is historical and comparative across disciplines emphasizing the different modes of explanation and use of evidence in each field.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"26-139"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.103"},{"code":"21A.133","title":"Latin American Migrations","level":"U","description":"Examines economic, cultural, political, and social dimensions of past and present migrations from Latin America and the Hispanic Caribbean to, from, and within the United States. Explores Latina/o community dynamics, politics of migrant labor, relational formations of race, and transnational forms of belonging. Students analyze ethnographies, films, visual arts, journalism, and music to study migration using central analytic concepts from anthropology, sociology, ethnic studies, and Latinx studies.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.133"},{"code":"21A.155","title":"Food, Culture, and Politics","level":"U","description":"Explores connections between what we eat and who we are through cross-cultural study of how personal identities and social groups are formed via food production, preparation, and consumption. Organized around critical discussion of what makes 'good' food good (healthy, authentic, ethical, etc.). Uses anthropological and literary classics as well as recent writing and films on the politics of food and agriculture. Instruction and practice in written and oral communication provided.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"24-307"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.155"},{"code":"21A.500","title":"Technology and Culture","level":"U","description":"Examines the intersections of technology, culture, and politics in a variety of social and historical settings ranging from 19th-century factories to 21st-century techno dance floors, from Victorian London to anything-goes Las Vegas. Discussions and readings organized around three questions: what cultural effects and risks follow from treating biology as technology; how computers have changed the way we think about ourselves and others; and how politics are built into our infrastructures. Explores the forces behind technological and cultural change; how technological and cultural artifacts are understood and used by different communities; and whether, in what ways, and for whom technology has produced a better world. Limited to 50.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"21:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.500"},{"code":"21A.501","title":"Art, Craft, Science","level":"U","description":"Examines how people learn, practice, and evaluate traditional and contemporary craft techniques. Social science theories of design, embodiment, apprenticeship learning, skill, labor, expertise, and tacit knowledge are used to explore distinctions among art, craft, and science. Also discusses the commoditization of craft into market goods, collectible art, and tourism industries. Ethnographic and historical case studies include textiles, Shaker furniture, glassblowing, quilting, cheesemaking, industrial design, home and professional cooking, factory and laboratory work, CAD/CAM. Demonstrations, optional field trips, and/or hands-on craft projects may be included. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.501"},{"code":"21A.503","title":"The Human Past: Introduction to Archaeology","level":"U","description":"From an archaeological perspective, examines ancient human activities and the forces that shaped them. Draws on case studies from the Old and/or New World. Exposes students to various classes of archaeological data, such as stone, bone, and ceramics, that help reconstruct the past.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:00","room":"4-231"}]},{"type":"Recitation","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"4-261"},{"days":["R"],"start":"16:00","end":"17:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.503"},{"code":"21A.505","title":"The Anthropology of Sound","level":"U","description":"Examines the ways humans experience sound and how perceptions and technologies of sound emerge from cultural, economic, and historical worlds. Consider how the sound/noise/music boundaries have been imagined, created, and modeled across sociocultural and historical contexts. Learn how environmental, linguistic, and musical sounds are construed cross-culturally as well as the rise of telephony, architectural acoustics, sound recording, multi-channel and spatial mix performance, and the globalized travel of these technologies. Questions of sound ownership, property, authorship, remix, and copyright in the digital age are also addressed.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.505"},{"code":"21A.511","title":"Hacking from the South","level":"U","description":"Using anthropological perspectives to propose critically reflexive modes of participation in existing socio-technical systems, students draw on ethnographic case studies to understand how practices and definitions of 'hacking' are grounded in specific political and cultural contexts. With a focus on the Global South (Africa, Latin America, Caribbean, Middle East, Asia and Southeast Asia, Oceania), examines the relationship between international development and technological empowerment by interrogating assumptions associated with particular locations and peoples, especially those constructed as peripheral to geographic centers of power. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.511"},{"code":"21A.525","title":"Oceans and Us","level":"U","description":"Explores how people have understood and encountered the ocean, cross-culturally, as a site of danger, pleasure, travel, food-procurement, commerce, and tourism. Topics include imperial voyaging, piracy, the invention of seaside vacations, the politics of fishing, the culture of onboard living in surface and submarine ships, the rise of undersea entertainment and documentary, regimes of managing maritime spaces and species, and the emergence of the ocean as an object of global ecological concern, particularly around climate change and sea level rise.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.525"},{"code":"21A.539","title":"Hacking from the South","level":"G","description":"Using anthropological perspectives to propose critically reflexive modes of participation in existing socio-technical systems, students draw on ethnographic case studies to understand how practices and definitions of 'hacking' are grounded in specific political and cultural contexts. With a focus on the Global South (Africa, Latin America, Caribbean, Middle East, Asia and Southeast Asia, Oceania), examines the relationship between international development and technological empowerment by interrogating assumptions associated with particular locations and peoples, especially those constructed as peripheral to geographic centers of power. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.539"},{"code":"21A.802","title":"Seminar in Ethnography and Fieldwork","level":"U","description":"Introduction to ethnographic practices: the study of and communicating about culture. Subject provides instruction and practice in writing, revision of fieldnotes, and a final paper. Preference to Anthropology majors and minors.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"E53-354"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.802"},{"code":"21A.819","title":"Ethnographic Research Methods","level":"G","description":"Training in the design and practice of qualitative research. Organized around illustrative texts, class exercises, and student projects. Topics include the process of gaining access to and participating in the social worlds of others; techniques of observation, fieldnote-taking, researcher self-monitoring and reflection; methods of inductive analysis of qualitative data including conceptual coding, grounded theory, and narrative analysis. Discussion of research ethics, the politics of fieldwork, modes of validating researcher accounts, and styles of writing up qualitative field research.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"E53-354"}]}],"url":"http://student.mit.edu/catalog/m21Aa.html#21A.819"},{"code":"21G.015","title":"Introduction to Buddhism, Mindfulness, and Meditation","level":"U","description":"Companion to the Fitness and Meditation class offered through MIT's Wellness program. Introduces students to the basic ideas of Buddhism, the history of Buddhism's transmission through East Asia, and core aspects of the philosophy of Humanistic Buddhism, including the role of meditation and mindfulness in Buddhist practice. Meets with the MIT Wellness Fitness and Meditation class; students must enroll in both to receive credit. Subject can count toward the 6-unit discovery-focused credit limit for first-year students. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"W35-199"}]}],"url":"http://student.mit.edu/catalog/m21Ga.html#21G.015"},{"code":"21G.042","title":"Three Kingdoms: From History to Fiction, Comic, Film, and Game","level":"U","description":"Analyzing core chapters of the great Chinese epic novel, Three Kingdoms, and its adaptations across diverse media, considers what underlies the appeal of this classic narrative over the centuries. Through focus on historical events in the period 206 BC to AD 280, examines the representation of power, diplomacy, war, and strategy, and explores the tension among competing models of political authority and legitimacy. Covers basic elements of classical Chinese political and philosophical thought, and literary and cultural history. Final group project involves digital humanities tools. Readings in translation. Films and video in Chinese with English subtitles.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Ga.html#21G.042"},{"code":"21G.061","title":"Literature and Existentialism","level":"U","description":"Studies major literary works associated with the 19th- and 20-century philosophical movement known as existentialism. Through close reading of these works, students explore how existentialist writers grappled with the question of death; the nature of free will; emotions like boredom, disgust, and radical doubt; and the fate of the individual in a modernity marked by war, illogic, and absurdity. Includes novels, short stories, and aphorisms by Sartre, Camus, Dostoevsky, Kafka, Hesse, Chopin, and Nietzsche; plays by Beckett and Stoppard; and films by Bergman, Tarkovsky, and others. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"56-114"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"2-147"},{"days":["R"],"start":"14:30","end":"16:00","room":"2-147"}]}],"url":"http://student.mit.edu/catalog/m21Ga.html#21G.061"},{"code":"21G.086","title":"20th Century Ukraine and Russia: Entangled Histories and Identity Politics","level":"U","description":"Explores the political and historical evolution of relations between Ukraine and Russia from 1900 to the present, with particular focus on the Soviet period from 1917 onward. Examines Ukrainian debates about autonomy and independence in the pre-revolutionary period; the revolutions of 1905 and 1917; the creation of the new Soviet state; the wars of 1917-1922; industrialization and collectivization, including the famines of 1932-1933; Stalinism; World War II; reform and stagnation; attempts at reform under Gorbachev; and, finally, the dramatic divergence of the two regions after 1991. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"56-154"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"56-154"},{"days":["R"],"start":"13:00","end":"14:30","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21Ga.html#21G.086"},{"code":"21G.101","title":"Chinese I (Regular)","level":"U","description":"Introduction to modern standard Chinese (Mandarin) with emphasis on developing conversational skills by using fundamental grammatical patterns and vocabulary in functional and culturally suitable contexts. Basic reading and writing are also taught. For graduate credit, see 21G.151. Placement interview with instructors required of students who have had prior exposure to Chinese before or on Reg Day. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"10:00","end":"11:00","room":"66-144"},{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"16-672"},{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.101"},{"code":"21G.103","title":"Chinese III (Regular)","level":"U","description":"Continuing instruction in spoken and written Chinese, with particular emphasis on consolidating basic conversational skills and improving reading confidence and depth. Lab work required. Placement interview with instructors before or on Reg. Day required of students who have had prior exposure to Chinese elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"09:00","end":"10:00","room":"16-644"},{"days":["M","T","R","F"],"start":"10:00","end":"11:00","room":"14N-221"},{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.103"},{"code":"21G.105","title":"Chinese V (Regular): Discovering Chinese Cultures and Societies","level":"U","description":"Students develop more sophisticated conversational and reading skills by combining traditional textbook material with their own explorations of Chinese speaking societies, using the human, literary, and electronic resources available at MIT and in the Boston area. Placement interview on or before Reg. Day required of students who have had prior exposure to Chinese elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.105"},{"code":"21G.107","title":"Chinese I (Streamlined)","level":"U","description":"The first term streamlined sequence. Designed for students who have conversational skills (typically gained from growing up in a Chinese speaking environment) without a corresponding level of literacy. For graduate credit see 21G.157. Placement interview on or before Reg. Day required of students who have had prior exposure to Chinese elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"1-273"},{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.107"},{"code":"21G.109","title":"Chinese III (Streamlined)","level":"U","description":"Intermediate level subject in streamlined sequence. Designed for students who have conversational skills (typically gained from growing up in a Chinese speaking environment) without a corresponding level of literacy. Consolidates conversation skills, improves reading confidence and broadens composition style. Placement interview on or before Reg. Day required of students who have had prior exposure to Chinese elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"1-277"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"16-672"},{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.109"},{"code":"21G.111","title":"Chinese Calligraphy","level":"U","description":"Provides an introduction to the ancient art of Chinese calligraphy and its traditional uses. Studies the history of the Chinese writing system and develops skills through guided reading, classroom discussion, and systematic practice with brush and ink. Students work on a small calligraphy project based on their own interest. Taught in English; no prior knowledge of Chinese language required. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"2-142"}]}],"url":"http://student.mit.edu/catalog/m21Ga.html#21G.111"},{"code":"21G.113","title":"Chinese V (Streamlined)","level":"U","description":"Advanced level subject in streamlined sequence. Designed for students who have conversational skills (typically gained from growing up in a Chinese speaking environment) without a corresponding level of literacy. Students conduct their own explorations of modern China using online and print materials, as well as interviews with Chinese in the Boston area. Placement interview on or before Reg. Day required of students who have had prior exposure to Chinese elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"14E-310"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.113"},{"code":"21G.121","title":"Chinese for Professional Communications","level":"U","description":"Students read and react to authentic materials centering on four areas — business, technology, medical, and students' own choices of academic interests. Students develop advanced-mid speaking skills in a formal context, understand main ideas of lengthy and argumentative texts, interpret related talks and speeches, and present their thoughts in structured essays. Taught entirely in Chinese. No listeners. Limited to 16 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.121"},{"code":"21G.133","title":"Three Kingdoms: From History to Fiction, Comic, Film, and Game","level":"U","description":"Analyzing core chapters of the great Chinese epic novel, Three Kingdoms, and its adaptations across diverse media, considers what underlies the appeal of this classic narrative over the centuries. Through focus on historical events in the period 206 BC to AD 280, examines the representation of power, diplomacy, war, and strategy, and explores the tension among competing models of political authority and legitimacy. Covers basic elements of classical Chinese political and philosophical thought, and literary and cultural history. Final group project involves digital humanities tools. Readings in translation. Films and video in Chinese with English subtitles. Taught in English with a project that requires research in Chinese. Preference to students in the Chinese minor","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.133"},{"code":"21G.151","title":"Chinese I (Regular)","level":"G","description":"Introduction to modern standard Chinese (Mandarin). For a full description, see 21G.101. For undergraduate credit see 21G.101. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"10:00","end":"11:00","room":"66-144"},{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"16-672"},{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.151"},{"code":"21G.153","title":"Chinese III (Regular)","level":"G","description":"Continuing instruction in spoken and written Chinese, with particular emphasis on consolidating basic conversational skills and improving reading confidence and depth. For a full description, see 21G.103. For undergraduate credit see 21G.103. Limited to 16. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"09:00","end":"10:00","room":"16-644"},{"days":["M","T","R","F"],"start":"10:00","end":"11:00","room":"14N-221"},{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.153"},{"code":"21G.157","title":"Chinese I (Streamlined)","level":"G","description":"Introduction to modern standard Chinese (Mandarin) for students with some speaking ability but little reading ability. For full description, see 21G.107. For undergraduate credit see 21G.107. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"1-273"},{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.157"},{"code":"21G.159","title":"Chinese III (Streamlined)","level":"G","description":"Intermediate level subject in streamlined sequence. For a full description, see 21G.109. For undergraduate credit see 21G.109. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"1-277"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"16-672"},{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Gb.html#21G.159"},{"code":"21G.219","title":"Foundations of Academic and Professional Writing (ELS)","level":"G","description":"Writing module for high-intermediate ELS students who wish to review and practice accurate grammar, effective sentence and paragraph structure, punctuation, and word choice. Short weekly writing assignments with extensive editing required. Meets with 21W.220 when offered concurrently. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"17:30","end":"19:00","room":"4-249"},{"days":["T","R"],"start":"12:00","end":"13:30","room":"26-142"}]}],"url":"http://student.mit.edu/catalog/m21Gc.html#21G.219"},{"code":"21G.222","title":"Expository Writing for Bilingual Students","level":"U","description":"Formulating, organizing, and presenting ideas clearly in writing. Reviews basic principles of rhetoric. Focuses on development of a topic, thesis, choice of appropriate vocabulary, and sentence structure to achieve purpose. Develops idiomatic prose style. Gives attention to grammar and vocabulary usage. Special focus on strengthening skills of bilingual students. Intended to be taken during the student's first year at MIT. Priority given to students recommended for 21W.222 based on summer FEE results. Limited to 15; undergraduates only.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14N-221"},{"days":["T","R"],"start":"15:30","end":"17:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/archive/spring/m21Gc.html#21G.222"},{"code":"21G.224","title":"Listening, Speaking, and Pronunciation (ELS)","level":"G","description":"Designed for high-intermediate ELS students who need to develop better listening comprehension and oral skills. Involves short speaking and listening assignments with extensive exercises in accurate comprehension, pronunciation, stress and intonation, and expression of ideas. Includes frequent video- and audio-recording for analysis and feedback. Meets with 21W.223 when offered concurrently. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"17:30","end":"19:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/archive/spring/m21Gc.html#21G.224"},{"code":"21G.225","title":"Advanced Workshop in Writing for Science and Engineering (ELS)","level":"G","description":"Analysis and practice of various forms of scientific and technical writing, from memos to journal articles. Strategies for conveying technical information to specialist and non-specialist audiences. The goal of the workshop is to develop effective writing skills for academic and professional contexts. Models, materials, topics, and assignments vary from term to term. Meets with 21W.226 when offered concurrently. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:30","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/archive/spring/m21Gc.html#21G.225"},{"code":"21G.226","title":"Advanced Workshop in Writing for Science and Engineering (ELS)","level":"U","description":"Analysis and practice of various forms of scientific and technical writing, from memos to journal articles. Strategies for conveying technical information to specialist and non-specialist audiences. The goal of the workshop is to develop effective writing skills for academic and professional contexts. Models, materials, topics, and assignments vary from term to term. Meets with 21W.225 when offered concurrently. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:30","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/archive/spring/m21Gc.html#21G.226"},{"code":"21G.232","title":"Advanced Speaking and Critical Listening Skills (ELS)","level":"G","description":"For advanced students who wish to build confidence and skills in spoken English. Focuses on the appropriate oral presentation of material in a variety of professional contexts: group discussions, classroom explanations and interactions, and theses/research proposals. Valuable for those who intend to teach or lecture in English. Includes frequent video- and audio-recording for analysis and feedback. Develops effective speaking and listening skills for academic and professional contexts. Models, materials, topics and assignments vary from term to term. May be repeated for credit with permission of the instructor. Meets with 21W.233 when offered concurrently. Limited to 15 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/archive/spring/m21Gc.html#21G.232"},{"code":"21G.233","title":"Advanced Speaking and Critical Listening Skills (ELS)","level":"U","description":"For advanced students who wish to build confidence and skills in spoken English. Focuses on the appropriate oral presentation of material in a variety of professional contexts: group discussions, classroom explanations and interactions, and theses/research proposals. Valuable for those who intend to teach or lecture in English. Includes frequent video- and audio-recording for analysis and feedback. Develops effective speaking and listening skills for academic and professional contexts. Models, materials, topics and assignments vary from term to term. May be repeated for credit with permission of the instructor. Meets with 21W.232 when offered concurrently.  Limited to 15 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/archive/spring/m21Gc.html#21G.233"},{"code":"21G.301","title":"French I","level":"U","description":"Introduction to the French language and culture with emphasis on the acquisition of vocabulary and grammatical concepts through active communication. Conducted entirely in French. Exposure to the language via a variety of authentic sources such as the Internet, audio, video and printed materials which help develop cultural awareness as well as linguistic proficiency. Coordinated language lab program. For graduate credit see 21G.351. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"14N-225"},{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.301"},{"code":"21G.302","title":"French II","level":"U","description":"Continuation of introductory course to the French language and culture with emphasis on acquisition of vocabulary and grammatical concepts through active communication. Conducted entirely in French. Exposure to the language via a variety of authentic sources such as the Internet, audio, video and printed materials which help develop cultural awareness as well as linguistic proficiency. Coordinated language lab. For graduate credit see 21G.352. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"14E-310"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"14E-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.302"},{"code":"21G.303","title":"French III","level":"U","description":"Third subject in the French language sequence. Systematic work on grammar and vocabulary expands skills in understanding, speaking, reading and writing in French. Intercultural exploration through a variety of authentic materials, such as music, videos, films, newspapers, and excerpts from literary texts. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"14N-225"},{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.303"},{"code":"21G.304","title":"French IV","level":"U","description":"Fourth subject in the French language sequence. Focuses on language and intercultural understanding. Students work with a variety of materials such as surveys, newspapers, commercials, films and music. Systematic work on grammar and vocabulary expands students' skills in understanding, speaking, reading, and writing. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"4-249"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"1-379"}]},{"type":"Lab","options":[{"days":["W"],"start":"11:00","end":"12:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.304"},{"code":"21G.308","title":"Writing (Like the) French","level":"U","description":"For students who wish to continue with language study before taking upper-level subjects in literature or culture. Emphasis on development of reading and writing skills, review of the basic concepts of French grammar, and acquisition of precise vocabulary through the use of printed materials, short stories, and poems. Taught in French.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.308"},{"code":"21G.313","title":"Francophone Cultures Through the Arts","level":"U","description":"Explores contemporary Francophone cultures through cinema, music, and visual arts. Studies how artists represent cultural life and social issues in different Francophone contexts using four themes: identities, memory, social justice, and love. Combines critical study with creative practice through projects such as storyboards, collages, and short audio-visual pieces. Highlights the use of French as both a medium of communication and a medium of artistic expression. Taught in French. Enrollment limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"1-379"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.313"},{"code":"21G.320","title":"Introduction to French Literature","level":"U","description":"A basic study of major French literary genres — poetry, drama, and fiction — and an introduction to methods of literary analysis. Authors include: Voltaire, Balzac, Sand, Baudelaire, Apollinaire, Camus, Sartre, Ionesco, Duras, and Tournier. Special attention devoted to the improvement of French language skills. Taught in French.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.320"},{"code":"21G.321","title":"Childhood and Youth in French and Francophone Cultures","level":"U","description":"Studies the transformation of childhood and youth since the 18th century in France, as well as the development of sentimentality within the family in a francophone context. Examines the personification of children, both as a source of inspiration for artistic creation and a political ideal aimed at protecting future generations. Considers various representations of childhood and youth in literature (e.g., Pagnol, Proust, Sarraute, Laye, Morgiévre), movies (e.g., Truffaut), and songs (e.g., Brel, Barbara). Taught in French.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.321"},{"code":"21G.333","title":"French III","level":"G","description":"Third subject in the French language sequence. Systematic work on grammar and vocabulary expands skills in understanding, speaking, reading and writing in French. Intercultural exploration through a variety of authentic materials, such as music, videos, films, newspapers, and excerpts from literary texts. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"14N-225"},{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.333"},{"code":"21G.334","title":"French IV","level":"G","description":"Fourth subject in the French language sequence. Focuses on language and intercultural understanding. Students work with a variety of materials such as surveys, newspapers, commercials, films and music. Systematic work on grammar and vocabulary expands students' skills in understanding, speaking, reading, and writing. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"4-249"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"1-379"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.334"},{"code":"21G.351","title":"French I","level":"G","description":"Introduction to the French language and culture with emphasis on acquisition of vocabulary and grammatical concepts through active communication. Conducted entirely in French. Exposure to the language via a variety of authentic sources such as the Internet, audio, video and printed materials which help develop cultural awareness and linguistic proficiency. Coordinated language lab program. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"14N-225"},{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.351"},{"code":"21G.352","title":"French II","level":"G","description":"Continuation of introductory course to the French language and culture with emphasis on acquisition of vocabulary and grammatical concepts through active communication. Conducted entirely in French. Exposure to the language via a variety of authentic sources such as the Internet, audio, video and printed materials which help develop cultural awareness as well as linguistic proficiency. Coordinated language lab. Same as 21G.302, but for graduate credit. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"14E-310"},{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"14E-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.352"},{"code":"21G.353","title":"Understanding Contemporary French Politics","level":"U","description":"Examines French politics since 1958. Analyzes how politics has deeply influenced cultural and social life in France, including daily interactions. Questions public controversies and history's political cleavages, from the Algerian war to postcolonial issues, from the birth of the European construction to the Covid crisis. To explore French institutions and understand the impact of political issues in contemporary France, students 'run' for the French presidency by preparing historical notes, delivering speeches, participating in a first-round presidential debate, and submitting a final political statement. Taught in French. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Gd.html#21G.353"},{"code":"21G.401","title":"German I","level":"U","description":"Introduction to German language and culture. Acquisition of vocabulary and grammatical concepts through active communication. A variety of contemporary sources, including online as well as printed materials, audio, and video, provide direct exposure to German language and culture. Development of effective basic communication skills to participate in everyday conversation and cultural situations. For graduate credit, see 21G.451. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"09:00","end":"10:00","room":"16-676"},{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.401"},{"code":"21G.402","title":"German II","level":"U","description":"Expansion of basic communication skills and further development of linguistic and cultural competencies. Review and completion of basic grammar, building of vocabulary, and practice in writing short essays. Reading of short literary texts. Exposure to history and culture of the German-speaking world through contemporary online materials, audio, and video. For graduate credit see 21G.452. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.402"},{"code":"21G.403","title":"German III","level":"U","description":"Expands skills in speaking, reading, listening, and writing and cultural competency. Develops analytic and interpretative skills through media selections on contemporary issues in the German-speaking world. Discussions and compositions as well as review of grammar and development of vocabulary-building strategies. Recommended for students with two years of high school German. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"16-654"},{"days":["M","T","R","F"],"start":"16:00","end":"17:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.403"},{"code":"21G.404","title":"German IV","level":"U","description":"Discussion and exploration of topics in their current cultural, social, political, and historical contexts in the German-speaking world. Further refinement of oral and written expression and expansion of communicative competence in practical everyday situations. Development of interpretive skills, using literary texts and contemporary media texts (film, TV broadcasts, Web materials). Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.404"},{"code":"21G.412","title":"Advanced German: Literature and Culture","level":"U","description":"Explores representative and influential works from the 19th century to the present, through literary texts (short prose, drama, poetry), radio plays, art, animated short film, and architecture. Discusses the construction and social function of these works. Provides students with ample opportunity to enhance their German orally and in writing. Topics include questions of how Germany is shaped by its history, debates about identity and identity formation, technology and the human as machine, science and ethics in the context of the present climate emergency. Includes works by E.T.A. Hoffmann, Kafka, Dürrenmatt, and Herta Müller. Taught in German.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.412"},{"code":"21G.451","title":"German I","level":"G","description":"Introduction to German language and culture. Acquisition of vocabulary and grammatical concepts through active communication. A variety of contemporary sources, such as online as well as printed materials, audio, and video, provide direct exposure to German language and culture. Development of effective basic communication skills to participate in everyday conversation and cultural situations. For undergraduate credit, see 21G.401. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"09:00","end":"10:00","room":"16-676"},{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.451"},{"code":"21G.452","title":"German II","level":"G","description":"Expansion of basic communication skills and further development of linguistic and cultural competencies. Review and completion of basic grammar, building of vocabulary, and practice in writing short essays. Reading of short literary texts. Exposure to history and culture of the German-speaking world through contemporary online materials, audio, and video. For undergraduate credit, see 21G.402. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.452"},{"code":"21G.453","title":"German III","level":"G","description":"Expands skills in speaking, reading, listening, and writing and cultural competency. Develops analytic and interpretative skills through media selections on contemporary issues in the German-speaking world. Discussions and compositions as well as review of grammar and development of vocabulary-building strategies. Recommended for students with two years of high school German. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"16-654"},{"days":["M","T","R","F"],"start":"16:00","end":"17:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.453"},{"code":"21G.454","title":"German IV","level":"G","description":"Discussion and exploration of topics in their current cultural, social, political, and historical contexts in the German-speaking world. Further refinement of oral and written expression and expansion of communicative competence in practical everyday situations. Development of interpretive skills, using literary texts and contemporary media texts (film, TV broadcasts, Web materials). Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"14N-225"}]}],"url":"http://student.mit.edu/catalog/m21Ge.html#21G.454"},{"code":"21G.501","title":"Japanese I","level":"U","description":"Introduction to modern standard Japanese. Emphasis on developing proficiency in speaking and listening, using basic grammar and vocabulary. Basic skills in reading and writing are also taught. Lab work required. For graduate credit see 21G.551. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"14:00","end":"15:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.501"},{"code":"21G.503","title":"Japanese III","level":"U","description":"Students further develop their skills in speaking, listening, reading, and writing. Involves continued vocabulary and kanji building. Coordinated language lab. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.503"},{"code":"21G.505","title":"Japanese V","level":"U","description":"Systematic development of reading, writing, and oral communication skills. Introduction to advanced grammar that deepens the understanding of Japanese culture and society through reading and discussion. Lab work required. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:00","end":"10:00","room":"14N-313"},{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.505"},{"code":"21G.551","title":"Japanese I","level":"G","description":"Introduction to modern standard Japanese. Emphasis on developing proficiency in speaking and listening, using basic grammar and vocabulary. Basic skills in reading and writing are also taught. Lab work required. Same as 21G.501, but for graduate credit.  Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"14:00","end":"15:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.551"},{"code":"21G.553","title":"Japanese III","level":"U","description":"Students further develop their skills in speaking, listening, reading, and writing. Involves continued vocabulary and kanji building. Coordinated language lab. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.553"},{"code":"21G.611","title":"Russian I (Hybrid)","level":"U","description":"Emphasizes the development of communicative and cultural competence, as well as mastery of the foundations of Russian grammar and vocabulary. Using video, internet resources, and varied cultural materials, students work on developing speaking, reading, and writing skills. Conducted in both Russian and English. Designed for students with no knowledge of Russian. Combines in-person and remote instruction. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"16:00","end":"17:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gm.html#21G.611"},{"code":"21G.613","title":"Russian III (Hybrid)","level":"U","description":"Continuing instruction in Russian language and culture with emphasis on acquisition of vocabulary and grammatical concepts through active communication. Aims to achieve simultaneous progression of four skills ? listening, speaking, reading, and writing. Develops communicative skills necessary for personal and professional interaction in a Russian-language environment. Provides exposure to the language via films, internet resources, and literary texts that are integrated in grammar instruction and conversation tasks. Combines in-person and remote instruction. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"16:00","end":"17:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Gm.html#21G.613"},{"code":"21G.616","title":"Advanced Russian: Explorations in Russian Culture, Society, and Media","level":"U","description":"Advanced work to further develop oral and written communication skills in Russian. Explores various topics in print and digital media, film, society, and culture focusing on Russian-speaking communities in different countries. Engages students in cross-cultural comparisons and offers an opportunity to interact with native speakers through guest visits and interviews. Focuses on developing higher-level vocabulary, listening, speaking, and writing skills. Taught in Russian. Topics vary term to term. Open to advanced students of Russian and heritage speakers. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"15:00","end":"16:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Gm.html#21G.616"},{"code":"21G.631","title":"Russian I (Hybrid)","level":"G","description":"Emphasizes the development of communicative and cultural competence, as well as mastery of the foundations of Russian grammar and vocabulary. Using video, internet resources, and varied cultural materials, students work on developing speaking, reading, and writing skills. Conducted in both Russian and English. Designed for students with no knowledge of Russian. Combines in-person and remote instruction. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"16:00","end":"17:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gm.html#21G.631"},{"code":"21G.633","title":"Russian III (Hybrid)","level":"G","description":"Continuing instruction in Russian language and culture with emphasis on acquisition of vocabulary and grammatical concepts through active communication. Aims to achieve simultaneous progression of four skills — listening, speaking, reading, and writing. Develops communicative skills necessary for personal and professional interaction in a Russian-language environment. Provides exposure to the language via films, internet resources, and literary texts that are integrated in grammar instruction and conversation tasks. Combines in-person and remote instruction. For undergraduate credit, see 21G.613. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"16:00","end":"17:00","room":"16-676"}]}],"url":"http://student.mit.edu/catalog/m21Gm.html#21G.633"},{"code":"21G.701","title":"Spanish I","level":"U","description":"For students with no previous knowledge of Spanish. Introduction to understanding, speaking, reading, and writing Spanish. Maximal use of fundamentals of grammar in active communication. Audio- and video-based language laboratory program coordinated with and supplemented to class work. For graduate credit see 21G.751. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"12:00","end":"13:00","room":"16-668"},{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.701"},{"code":"21G.702","title":"Spanish II","level":"U","description":"Continues the study of Spanish language and culture using audio, video and print materials, feature films and popular music from Latin America and Spain. Emphasizes writing, vocabulary acquisition, and the study of more complex grammatical structures. Students develop oral skills through group interaction and short presentations. For graduate credit see 21G.752. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"09:00","end":"10:00","room":"16-668"},{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.702"},{"code":"21G.703","title":"Spanish III","level":"U","description":"Aims at consolidation and expansion of skills in listening comprehension, speaking, reading, and writing. Uses short stories and other readings, films, music, and Web projects (including a multimedia exchange with students in Spain) to study issues of historical and current interest in Hispanic culture. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"16-676"},{"days":["M","T","W","R"],"start":"11:00","end":"12:00","room":"16-676"},{"days":["M","T","W","R"],"start":"13:00","end":"14:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.703"},{"code":"21G.704","title":"Spanish IV","level":"U","description":"Continued study of the language, literature, and culture of Spanish-speaking countries to improve oral and written communication. Materials include contemporary Spanish and Latin American films, literary texts (short stories, poetry and a novel), online video interviews with a variety of Spanish-speakers and other Web resources. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"11:00","end":"12:00","room":"16-644"},{"days":["M","T","W","R"],"start":"12:00","end":"13:00","room":"16-644"},{"days":["M","T","W","R"],"start":"14:00","end":"15:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.704"},{"code":"21G.707","title":"Graphic Stories: Spanish and Latin American Comics","level":"U","description":"Fosters development of spoken and written skills to improve fluency and style in Spanish while exploring graphic novels, comics, or sequential art, of the Spanish-Speaking world (Mexico, Puerto Rico, Argentina, Chile, Spain, and the USA). Special attention given to: autobiographical memory, gender identity, multiculturalism, transatlantic crossings, and science fiction. Small group work, class discussions, debates, and games will be used in order to expand students' vocabulary in a wide range of topics, as well as to improve command of the more problematic grammatical structures in Spanish. Taught in Spanish. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.707"},{"code":"21G.715","title":"Topics in Medicine and Public Health in the Hispanic World","level":"U","description":"Strengthens oral and written communication skills in Spanish by examining current topics in medicine and public health. Explores medical and health challenges in various Hispanic nations and among Spanish-speaking communities in the US. Topics include cultural narratives of illness, bioethical considerations of genetic research, women's reproductive rights, Cuba's export of healthcare workers, the ethical implications of medical decision-making, and euthanasia. Draws on sources from the humanities, social sciences and the arts that incorporate diverse perspectives on these issues. Focuses on the use of language in the construction of cultural metaphors and representations of illness and healing. Taught in Spanish. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.715"},{"code":"21G.719","title":"Spanish in Context: Social Movements and Cultural Change","level":"U","description":"Using authentic texts and media ? including films, stories, podcasts, and digital platforms from Mexico, Puerto Rico, Argentina, Peru, Spain, and the United States ? students develop advanced fluency, style, and cultural understanding. Topics include: identity, labor, race, migration, gender, sexuality, and environmental sustainability, with attention to how social justice movements across the Americas and Spain drive cultural change. Students expand vocabulary and refine complex grammar while engaging in small-group activities, debates, and discussions in Spanish. Emphasizes producing sophisticated oral and written communication across multiple genres. Speaking-intensive. Taught in Spanish. Enrollment limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.719"},{"code":"21G.731","title":"Creation of a Continent: Media Representations of Hispanic America, 1492 to present","level":"U","description":"Traces the creation of a new literature in Spanish to record and interpret New World experiences. Begins with excerpts from Columbus's diary and ends with writings on the late 19th-century Cuban and Puerto Rican independence movements. Pairs some of these pre-20th-century texts with more recent literary and film interpretations of the first 400 years of Hispanic American history. Conducted in Spanish.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.731"},{"code":"21G.734","title":"Introduction to Contemporary Hispanic Literature and Film","level":"U","description":"Focuses on literary and cinematic production in 20th- and 21st-century Spain and Latin America with a particular emphasis on how social, cultural, political, and technological changes led to aesthetic innovations. Topics include the literature of politics, the avant-garde and subsequent literary boom, the radical aesthetic of the post-Franco era, and post-modern film and art. Materials include short stories, novels, poetry, song, and film. Conducted in Spanish.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.734"},{"code":"21G.751","title":"Spanish I","level":"G","description":"For students with no previous knowledge of Spanish. Introduction to understanding, speaking, reading, and writing Spanish. Maximal use of fundamentals of grammar in active communication. Audio- and video-based language laboratory program coordinated with and supplementary to class work. Same as 21G.701, but for graduate credit. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"12:00","end":"13:00","room":"16-668"},{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.751"},{"code":"21G.752","title":"Spanish II","level":"G","description":"Introductory subject that continues the study of Spanish language and culture using audio, video and print materials, feature films and popular music from Latin America and Spain. Emphasizes writing, vocabulary acquisition, and the study of more complex grammatical structures. Group interaction and short oral presentations develop students' oral skills. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"09:00","end":"10:00","room":"16-668"},{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.752"},{"code":"21G.753","title":"Spanish III","level":"G","description":"Aims at consolidation and expansion of skills in listening comprehension, speaking, reading, and writing. Uses short stories and other readings, films, music, and Web projects (including a multimedia exchange with students in Spain) to study issues of historical and current interest in Hispanic culture. Same as 21G.703, but for graduate credit. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"16-676"},{"days":["M","T","W","R"],"start":"11:00","end":"12:00","room":"16-676"},{"days":["M","T","W","R"],"start":"13:00","end":"14:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.753"},{"code":"21G.754","title":"Spanish IV","level":"G","description":"Continued study of the language, literature, and culture of Spanish-speaking countries to improve oral and written communication. Materials include contemporary Spanish and Latin American films, literary texts (short stories, poetry and a novel), online video interviews with a variety of Spanish-speakers and other Web resources. Same as 21G.704, but for graduate credit. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"11:00","end":"12:00","room":"16-644"},{"days":["M","T","W","R"],"start":"12:00","end":"13:00","room":"16-644"},{"days":["M","T","W","R"],"start":"14:00","end":"15:00","room":"16-644"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.754"},{"code":"21G.821","title":"The Beat of Brazil: Language and Society Through Music","level":"U","description":"Presents an overview of Brazilian history, art, and culture from the late 19th century to the present day. Topics covered are woven into the larger theme of popular Brazilian music, and include the Modern Art Week of 1922, Candido Portinari's paintings, the Tropicalist art movement, and the role of artists and intellectuals during and after the military dictatorship. Identifies and distinguishes the main Brazilian musical styles, connecting them to specific historical periods and events, discussing how they reflect different notions of identity, and analyzing cultural production from a transnational perspective. Practice in listening, speaking, reading, and writing is provided, with strong emphasis on developing critical thinking. Taught in Portuguese. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gh.html#21G.821"},{"code":"21G.881","title":"Portuguese I (Hybrid)","level":"U","description":"Hybrid version of 21G.801/21G.851, which offers a combination of in-person and remote instruction. An introduction for students with little or no previous knowledge of Portuguese. Aims to achieve simultaneous progression of four skills - listening, speaking, reading, and writing. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gh.html#21G.881"},{"code":"21G.883","title":"Portuguese III Hybrid","level":"U","description":"Hybrid version of 21G.803/853, which offers a combination of in-person and remote instruction. A beginning intermediate language class that aims to expand and consolidate the student's basic linguistic skills, as well as several relevant cultural aspects of the Portuguese-speaking world. Includes a thorough review of grammar through exposure to input from various sources: written texts, movies, multi-media, and discussions in Portuguese. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gh.html#21G.883"},{"code":"21G.887","title":"Portuguese I (Hybrid)","level":"U","description":"Hybrid version of 21G.801/21G.851, which offers a combination of in-person and remote instruction. An introduction for students with little or no previous knowledge of Portuguese. Aims to achieve simultaneous progression of four skills - listening, speaking, reading, and writing. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gh.html#21G.887"},{"code":"21G.889","title":"Portuguese III (Hybrid)","level":"G","description":"Hybrid version of 21G.853, which offers a combination of in-person and remote instruction. A beginning intermediate language class that aims to expand and consolidate the students basic linguistic skills, as well as several relevant cultural aspects of the Portuguese-speaking world. Includes a thorough review of grammar through exposure to input from various sources: written texts, movies, multi-media, and discussions in Portuguese. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Gh.html#21G.889"},{"code":"21G.901","title":"Korean I","level":"U","description":"Introduction to modern standard Korean with emphasis on developing conversational skills by using fundamental grammatical patterns and vocabulary in functional and culturally suitable contexts. Basic reading and writing are also taught. Placement interview with instructors on or before Registration Day required of students who have had prior exposure to Korean elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"16-676"},{"days":["M","T","R","F"],"start":"15:00","end":"16:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Go.html#21G.901"},{"code":"21G.903","title":"Korean III","level":"U","description":"Continuing instruction in spoken and written Korean, with particular emphasis on consolidating basic conversational skills and improving reading confidence and depth. Lab work required. Placement interview with instructors on or before Registration Day required of students who have had prior exposure to Korean elsewhere. Limited to 16 per section. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"14N-313"},{"days":["M","T","R","F"],"start":"15:00","end":"16:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Go.html#21G.903"},{"code":"21G.905","title":"Korean V","level":"U","description":"Designed to improve students' skills in listening, reading, speaking, and writing in Korean. Explores various topics such as Korean contemporary culture, traditional holidays, humor, history, cultural heritage, daily life, and other related subjects. Students compare, in writing and speaking, the Korean context with their own backgrounds. Placement interview with instructors on or before Registration Day required of students who have had prior exposure to Korean elsewhere. Conducted entirely in Korean. Limited to 16 per section.","groups":[{"type":"Lecture","options":[{"days":["M","T","R"],"start":"16:00","end":"17:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Go.html#21G.905"},{"code":"21G.907","title":"Dynamic Korean: Topics in Language, Culture, and Society","level":"U","description":"Provides a bridge from structured language study to independent engagement with authentic texts and contemporary issues. Combines linguistic development within culture and sociolinguistic insight, encouraging students to think critically about how Korean language interacts with society. Focuses on evolving themes in Korean culture and communication to not only build advanced proficiency but also prepare students to apply Korean in academic, professional, and intercultural contexts. Subject is repeatable for credit. Taught in Korean. Limited to 16 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R"],"start":"16:00","end":"17:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Go.html#21G.907"},{"code":"21G.951","title":"Arabic I","level":"U","description":"Introduces students to the fundamentals of Modern Standard Arabic (MSA) using an integrated approach to develop skills in formal and colloquial Arabic and establish basic proficiency. With an overview of basic phonemes, vocabulary, grammatical structures, and the Arabic writing system, provides opportunities to practice the four skills of reading, writing, listening, and speaking. Introduces students to some of the diverse cultures of the Arabic-speaking world, in order to develop intercultural, communicative, and linguistic competencies. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"15:00","end":"16:00","room":"16-672"}]}],"url":"http://student.mit.edu/catalog/m21Gq.html#21G.951"},{"code":"21G.953","title":"Arabic III","level":"U","description":"Continues to develop speaking, listening, reading, and writing in Modern Standard Arabic (MSA). Expands formal, informal vocabulary, and expressions via class discussions and course materials. Assignments and activities focus on building communicative abilities in real life situations through literature, science, media, art, global social issues, and environmental studies. Students use authentic materials to enhance negotiation, reasoning, explaining, describing, and expressing opinions in Arabic. Students present one individual and one group project. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"16:00","end":"17:00","room":"16-672"}]}],"url":"http://student.mit.edu/catalog/m21Gq.html#21G.953"},{"code":"21G.955","title":"Arabic I","level":"G","description":"Introduces students to the fundamentals of Modern Standard Arabic (MSA) using an integrated approach to develop skills in formal and colloquial Arabic and establish basic proficiency. For a full description, see 21G.951. For undergraduate credit see 21G.951. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"15:00","end":"16:00","room":"16-672"}]}],"url":"http://student.mit.edu/catalog/m21Gq.html#21G.955"},{"code":"21G.957","title":"Arabic III","level":"G","description":"Continues to develop speaking, listening, reading, and writing in Modern Standard Arabic (MSA). For a full description, see 21G.953. For undergraduate credit see 21G.953. Limited to 18 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"16:00","end":"17:00","room":"16-672"}]}],"url":"http://student.mit.edu/catalog/m21Gq.html#21G.957"},{"code":"21G.991","title":"Korean I","level":"G","description":"Introduction to modern standard Korean with emphasis on developing conversational skills by using fundamental grammatical patterns and vocabulary in functional and culturally suitable contexts. Basic reading and writing are also taught. Placement interview with instructors on or before Registration Day required of students who have had prior exposure to Korean elsewhere. Same as 21G.901 but for graduate credit. Limited to 16 per section for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"12:00","end":"13:00","room":"16-676"},{"days":["M","T","R","F"],"start":"15:00","end":"16:00","room":"16-654"}]}],"url":"http://student.mit.edu/catalog/m21Go.html#21G.991"},{"code":"21G.993","title":"Korean III","level":"G","description":"Continuing instruction in spoken and written Korean, with particular emphasis on consolidating basic conversational skills and improving reading confidence and depth. Lab work required. Placement interview with instructors on or before Registration Day required of students who have had prior exposure to Korean elsewhere. Same as 21G.903 but for graduate credit. Limited to 16 per section for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","T","R","F"],"start":"13:00","end":"14:00","room":"14N-313"},{"days":["M","T","R","F"],"start":"15:00","end":"16:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21Go.html#21G.993"},{"code":"21G.S03","title":"Special Subject: Global Studies and Languages","level":"U","description":"Opportunity for undergraduate study of subject matter that is not covered in the regular curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","R","F"],"start":"13:00","end":"14:00","room":"16-668"}]}],"url":"http://student.mit.edu/catalog/m21Gt.html#21G.S03"},{"code":"21G.S51","title":"Special Subject: Japanese I","level":"U","description":"Experimental version of Japanese I, which offers a combination of in-person and remote instruction. Designed for students with no previous knowledge of the language, providing opportunities to acquire basic skills for conversation, reading and writing in Japanese. In in-person sessions, students participate in vigorous drill exercises and discussions, engaging in face-to-face interactions within an immersive learning environment, ensuring immediate feedback. In asynchronous sessions, students engage in asynchronous learning activities at their own pace. Activities include grammar and culture lessons, speaking and reading practice, as well as interactive pair/group work designed to develop students' communication skills, language proficiency, and collaborative abilities while deepening their understanding of the Japanese language and culture. Licensed for Fall 2025 by the Committee on Curricula. Limited to 16 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","R","F"],"start":"10:00","end":"11:00","room":"16-672"},{"days":["M","R","F"],"start":"11:00","end":"12:00","room":"16-672"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.S51"},{"code":"21G.S53","title":"Special Subject: Japanese III","level":"U","description":"Experimental version of Japanese III, which offers a combination of in-person and asynchronous remote instruction. Students further develop four basic skills in Japanese — listening, speaking, reading, and writing. Involves continuous expansion of vocabulary and kanji. Promotes the development of effective communication and collaborative skills, while nurturing learning autonomy. Aims to establish a solid linguistic foundation while deepening understanding of Japanese culture. Licensed for Fall 2025 by the Committee on Curricula. Limited to 16 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","R","F"],"start":"09:00","end":"10:00","room":"4-249"},{"days":["M","R","F"],"start":"11:00","end":"12:00","room":"4-249"},{"days":["M","R","F"],"start":"12:00","end":"13:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.S53"},{"code":"21G.S57","title":"Special Subject: Japanese I","level":"G","description":"Experimental version of Japanese I, which offers a combination of in-person and remote instruction. Designed for students with no previous knowledge of the language, providing opportunities to acquire basic skills for conversation, reading and writing in Japanese. In in-person sessions, students participate in vigorous drill exercises and discussions, engaging in face-to-face interactions within an immersive learning environment, ensuring immediate feedback. In asynchronous sessions, students engage in asynchronous learning activities at their own pace. Activities include grammar and culture lessons, speaking and reading practice, as well as interactive pair/group work designed to develop students' communication skills, language proficiency, and collaborative abilities while deepening their understanding of the Japanese language and culture. Licensed for Fall 2025 by the Committee on Graduate Programs. Limited 16 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","R","F"],"start":"10:00","end":"11:00","room":"16-672"},{"days":["M","R","F"],"start":"11:00","end":"12:00","room":"16-672"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.S57"},{"code":"21G.S59","title":"Special Subject: Japanese III","level":"G","description":"Experimental version of Japanese III, which offers a combination of in-person and asynchronous remote instruction. Students further develop four basic skills in Japanese — listening, speaking, reading, and writing. Involves continuous expansion of vocabulary and kanji. Promotes the development of effective communication and collaborative skills, while nurturing learning autonomy. Aims to establish a solid linguistic foundation while deepening understanding of Japanese culture. Licensed for Fall 2025 by the Committee on Graduate Programs. Limited to 16 for pedagogical reasons.","groups":[{"type":"Lecture","options":[{"days":["M","R","F"],"start":"09:00","end":"10:00","room":"4-249"},{"days":["M","R","F"],"start":"11:00","end":"12:00","room":"4-249"},{"days":["M","R","F"],"start":"12:00","end":"13:00","room":"4-249"}]}],"url":"http://student.mit.edu/catalog/m21Gf.html#21G.S59"},{"code":"21H.108","title":"Sexual and Gender Identities in the Modern United States","level":"U","description":"Provides an introduction to the history of gender, sex, and sexuality in the modern United States, from the end of the 19th century to the present. Surveys historical approaches to the field, emphasizing the changing nature of sexual and gender identities over time. Traces attempts to control, construct, and contain sexual and gender identities. Examines the efforts of those who worked to resist, reject, and reform institutionalized heterosexuality and mainstream configurations of gendered power.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-134"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.108"},{"code":"21H.130","title":"The Ancient World: Greece","level":"U","description":"History of Ancient Greece from the Bronze Age to the death of Alexander. Major social, economic, political, and religious trends. Homer, heroism, and the Greek identity; the hoplite revolution and the rise of the city-state; Herodotus, Persia, and the (re)birth of history; Empire, Thucydidean rationalism, and the Peloponnesian War; Aristotle, Macedonia, and Hellenism. Emphasis on use of primary sources in translation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:00","room":"4-145"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"66-154"},{"days":["F"],"start":"10:00","end":"11:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.130"},{"code":"21H.135","title":"J.R.R. Tolkien: Scholar, Author, and Thinker","level":"U","description":"Explores how an Oxford professor of medieval philology and literature wrote the most influential work of fantasy, The Lord of the Rings. Investigates how Tolkien's scholarship on Anglo-Saxon and Middle English, fascination with inventing languages, experiences during the First World War, and Catholic faith shaped the creation of his fantasy world often (mistakenly) called Middle Earth. Examines Tolkien's books within the context of his life, scholarship, ideas, and beliefs to uncover how an author of fantasy literature helped shape the image of the Middle Ages in the modern popular imagination. Considers the extent to which film adaptations do justice to the complexity of Tolkien's stories, themes, and characters.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.135"},{"code":"21H.141","title":"Renaissance to Revolution: Europe, 1300-1800","level":"U","description":"Provides an introduction to major political, social, cultural and intellectual changes in Europe from the beginnings of the Renaissance in Italy around 1300 to the outbreak of the French Revolution at the end of the 1700s. Focuses on the porous boundaries between categories of theology, magic and science. Examines how developments in these areas altered European political institutions, social structures, and cultural practices. Studies men and women, nobles and commoners, as well as Europeans and some non-Europeans with whom they came into contact.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.141"},{"code":"21H.151","title":"Dynastic China","level":"U","description":"Examines the first dynasty to 1800. Traces the rise of the world's first centralized bureaucratic state, the development of the world's oldest living written culture, and the formation of the pre-modern world's largest single commercial market. Studies women and men as they founded dynasties, engaged in philosophy, challenged orthodoxies, and invented technologies used around the globe. Explores China's past to understand the country's present, and reflects on what its stories mean for the global world.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.151"},{"code":"21H.185","title":"Environment and History","level":"U","description":"Focusing on the period from 1500 to the present, explores the influence of climate, topography, plants, animals, and microorganisms on human history and the reciprocal influence of people on the environment. Topics include the European encounter with the Americas, the impact of modern technology, and the current environmental crisis. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.185"},{"code":"21H.188","title":"History of the US West","level":"U","description":"Explores the US West as a place and a process. Reflects on the enduring political, economic, cultural, and environmental significance of a region constantly changing shape. Anchored in the period between the Gold Rush and the founding of Google, subject moves through the imaginaries (e.g., manifest destiny, frontier myth, global outposts), infrastructures (e.g., railroads, dams, and highways), and industries (e.g., mining, agriculture, tourism, and tech) most closely associated with western history. Asks how myriad peoples shaped and were shaped by processes of westward expansion, migration, industrialization, urbanization, suburbanization, and globalization.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.188"},{"code":"21H.227","title":"History of the US Supreme Court","level":"U","description":"Exploration of the historical development of constitutional law and the relationship between the Supreme Court and broader social, political, and cultural trends. Introduces major themes and patterns of change in American constitutional law since 1787, including federal-state relations, racial and gender equality, economic regulation, and civil liberties. Readings consist of original court cases, especially from the US Supreme Court, including cases of the current term.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.227"},{"code":"21H.245","title":"20th Century Ukraine and Russia: Entangled Histories and Identity Politics","level":"U","description":"Explores the political and historical evolution of relations between Ukraine and Russia from 1900 to the present, with particular focus on the Soviet period from 1917 onward. Examines Ukrainian debates about autonomy and independence in the pre-revolutionary period; the revolutions of 1905 and 1917; the creation of the new Soviet state; the wars of 1917-1922; industrialization and collectivization, including the famines of 1932-1933; Stalinism; World War II; reform and stagnation; attempts at reform under Gorbachev; and, finally, the dramatic divergence of the two regions after 1991. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"56-154"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"56-154"},{"days":["R"],"start":"13:00","end":"14:30","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.245"},{"code":"21H.274","title":"Creation of a Continent: Media Representations of Hispanic America, 1492 to present","level":"U","description":"Traces the creation of a new literature in Spanish to record and interpret New World experiences. Begins with excerpts from Columbus's diary and ends with writings on the late 19th-century Cuban and Puerto Rican independence movements. Pairs some of these pre-20th-century texts with more recent literary and film interpretations of the first 400 years of Hispanic American history. Conducted in Spanish.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.274"},{"code":"21H.276","title":"Medicine, Health, and Healing in the Global South","level":"U","description":"Through the lens of Latin America, explores the history of social medicine, a field that understands health and illness through structural determinants such as poverty, underdevelopment, and socio-demographic inequality. Topics include: Latin America's national initiatives — past and present — for social medicine; historical figures who trained as doctors but became presidents or revolutionaries; South-South cooperation in the field of medicine; and Indigenous practices to care and wellbeing. Explores the history of medical practices that defy Western paradigms and challenges students to think about the perils and possibilities of their own medical system and the diverse population it serves.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.276"},{"code":"21H.281","title":"MIT and Slavery: Research","level":"U","description":"Explores the influence of slavery and race on MIT's founding and early development, and the connections between slavery and the rise of sciences and engineering.  Students will have their research projects published through the MIT and Slavery website.  While 21H.281 and 21H.282 are sequential, students have the option of taking either or both.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/m21Ha.html#21H.281"},{"code":"21H.300","title":"The History of Now","level":"U","description":"Explores urgent issues shaping the world today and traces their historical roots. Uncovers how these issues evolved, how historical actors grappled with similar challenges, and how understanding the past can illuminate pathways for the future. Students combine rigorous historical analysis with public-facing work, including podcasts, virtual exhibits, short historical videos, or public history blogs. Topics vary. Repeatable for credit with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.300"},{"code":"21H.332","title":"Medieval Warfare","level":"U","description":"Investigates the organization and conduct of war in the medieval world, from barbarian invasions in Late Antiquity to the Ottoman conquest of Constantinople in 1453. Explores continuities and transformations in warfare from the late Roman empire to the successor kingdoms of medieval Europe, Byzantium, and the Muslim world. Examines the complex interplay between war, politics, and society, and problematizes popular images of medieval warfare as primitive, heroic, and chivalric. Topics include the barbarian invasions of the Roman empire, the expansion of Islam, Charlemagne's subjugation of the Saxons, the Viking raids, castle building and siege warfare, the Norman Conquest and Crusades, and ideologies of just war, holy war, and jihad.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"E51-393"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.332"},{"code":"21H.336","title":"The Making of a Roman Emperor","level":"U","description":"Through close examination of the emperor Augustus and his Julio-Claudian successors, this subject investigates how Roman emperors used art, architecture, coinage, and other media to create and project an image of themselves, how the surviving literary sources from the Roman period reinforced or subverted that image, and how both phenomena have contributed to post-classical perceptions of Roman emperors. Also considers works of Suetonius and Tacitus, and modern representations of the emperors such as those found in the films I, Claudius, Quo Vadis, and HBO's Rome series. Enrollment limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.336"},{"code":"21H.343","title":"Making Books in the Renaissance and Today","level":"U","description":"Explores the impact of new technology on the recording and distribution of words and images in Europe from 1400-1800. Assignments include essays and online projects. Students participate in the design and printing of an eight-page pamphlet on a hand-set printing press. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.343"},{"code":"21H.352","title":"Three Kingdoms: From History to Fiction, Comic, Film, and Game","level":"U","description":"Analyzing core chapters of the great Chinese epic novel, Three Kingdoms, and its adaptations across diverse media, considers what underlies the appeal of this classic narrative over the centuries. Through focus on historical events in the period 206 BC to AD 280, examines the representation of power, diplomacy, war, and strategy, and explores the tension among competing models of political authority and legitimacy. Covers basic elements of classical Chinese political and philosophical thought, and literary and cultural history. Final group project involves digital humanities tools. Readings in translation. Films and video in Chinese with English subtitles.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.352"},{"code":"21H.358","title":"Colonialism in South Asia and Africa: Race, Gender, Resistance","level":"U","description":"Provides a comparative perspective on the history of colonialism in India and Africa. Explores the political, social, and economic changes brought about by colonial rule. Discusses the international context for the emergence of European Imperialism in the 19th century; the nature of early colonial expansion and consolidation; the re-invention of tradition in colonial societies, especially with regard to racial and ethnic identity, gender, religion, and caste; and expressions of anti-colonial resistance. Students taking graduate version complete additional assignments. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:00","end":"13:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.358"},{"code":"21H.390","title":"Theories and Methods in the Study of History","level":"U","description":"Examines the distinctive ways in which historians in different parts of the world have approached the task of writing history. Explores methodologies used, such as political, social, economic, cultural, and popular histories through the reading and discussion of relevant and innovative texts. Introduces a variety of sources (archival documents, statistical data, film, fiction, memoirs, artifacts, and images) and the ways they can be used to research, interpret, and present the past. Assignments include an original research paper. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.390"},{"code":"21H.905","title":"Seminar in Economic History","level":"G","description":"Approaches the interplay of history and economics with a focus on how economists use history and how historians use economic ideas. Explores methods and topics, including the political economy of empire, poverty, environment, energy, and information. Class sessions include readings, discussion, and guest lectures.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"12:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.905"},{"code":"21H.958","title":"Colonialism in South Asia and Africa: Race, Gender, Resistance","level":"G","description":"Provides a comparative perspective on the history of colonialism in India and Africa. Explores the political, social, and economic changes brought about by colonial rule. Discusses the international context for the emergence of European Imperialism in the 19th century; the nature of early colonial expansion and consolidation; the re-invention of tradition in colonial societies, especially with regard to racial and ethnic identity, gender, religion, and caste; and expressions of anti-colonial resistance. Students taking graduate version complete additional assignments. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:00","end":"13:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.958"},{"code":"21H.991","title":"Theories and Methods in the Study of History","level":"G","description":"Examines the distinctive ways in which historians in different parts of the world have approached the task of writing history. Explores methodologies used, such as political, social, economic, cultural, and popular histories through the reading and discussion of relevant and innovative texts. Introduces a variety of sources (archival documents, statistical data, film, fiction, memoirs, artifacts, and images) and the ways they can be used to research, interpret, and present the past. Assignments include an original research paper. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.991"},{"code":"21H.S04","title":"Special Subject: History","level":"U","description":"Opportunity for group study of special subject not listed in the regular History curriculum.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"13:00","room":"8-119"}]}],"url":"http://student.mit.edu/catalog/m21Hb.html#21H.S04"},{"code":"21L.003","title":"Reading Fiction","level":"U","description":"Samples prose narrative from different traditions, examining texts that feature distinctive styles and formal rhythms in their social and historical contexts. May include European and US classics, alongside global and contemporary authors. Considers writing and reading as forms of social engagement, with special attention to the ways that authors borrow from and innovate on the past. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.003"},{"code":"21L.004","title":"Reading Poetry","level":"U","description":"Concentrates on close analysis of poems written in English in various forms (lyric, epic, dramatic). Syllabus varies from term to term but typically includes Shakespeare, Milton, Wordsworth, Blake, Keats, Whitman, Dickinson, Frost, Eliot, Langston Hughes, Lowell, and Plath. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"56-169"},{"days":["M","W"],"start":"19:00","end":"20:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.004"},{"code":"21L.009","title":"Shakespeare","level":"U","description":"Focuses on the close reading of six to eight of Shakespeare plays, as well as their adaptation for stage and/or film.  Selected texts cover the range of genres in which Shakespeare wrote (i.e., history, comedy, tragedy, and romance). Special emphasis in some terms on performances and adaptions of Shakespearean drama around the world. Plays studied vary across sections and from term to term, and have recently included Henry IV Part 1, Hamlet, A Midsummer Night's Dream, King Lear, Othello, and The Tempest. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.009"},{"code":"21L.011","title":"Introduction to Film Studies","level":"U","description":"Concentrates on close analysis and criticism of a wide range of films, including works from the early silent period, documentary and avant-garde films, European art cinema, and contemporary Hollywood fare. Through comparative reading of films from different eras and countries, students develop the skills to turn their in-depth analyses into interpretations and explore theoretical issues related to spectatorship. Syllabus varies from term to term, but usually includes such directors as Eisenstein, Fellini, Godard, Griffith, Hawks, Hitchcock, Kubrick, Kurosawa, Tarantino, Welles, and Wiseman.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"20:30","room":"3-270"}]},{"type":"Lab","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"1-190"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:30","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.011"},{"code":"21L.016","title":"Gods and Mortals","level":"U","description":"Introduces students to moral and philosophical questions that emerge from the study of pre-modern literature, such as how humans have grappled with life on earth and negotiated their relationships with the known and unknown, nature and the cosmos, past and future, the physical and the metaphysical, life and death, one another, and the divine. Focuses on careful reading of major works and authors, including selections from Sappho's lyric poems, Homer's Iliad and Odyssey, Virgil's Aeneid, Augustine's Confessions, and Dante's Inferno. Develops skills in close reading and in persuasive and personal analytical writing. Students have the opportunity to present on their readings and research in a variety of forms.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"66-160"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.016"},{"code":"21L.017","title":"The Art of the Probable","level":"U","description":"Examines literary texts and/or films in relation to the history of the idea of probability. Traces the growing importance of probability as a basic property of things and the world, as well as a measure of the reliability of our ideas and beliefs. Connects the development and use of probabilistic reasoning (e.g., in the lottery and in statistics) with literary and cultural concerns regarding the rationality of belief, risk and uncertainty, free will and determinism, chance and fate. Discussion of the work of scientific and philosophical pioneers of probabilistic thought (e.g., Pascal, Leibniz, Bernoulli, Laplace) in conjunction with works by Shakespeare, Voltaire, H. G. Wells, Pynchon and Stoppard, among others. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.017"},{"code":"21L.020","title":"Globalization:  The Good, the Bad and the In-Between","level":"U","description":"Examines the cultural paradoxes of contemporary globalization. Studies the cultural, artistic, social and political impact of globalization across international borders. Students analyze contending definitions of globalization and principal agents of change, and why some of them engender backlash; identify the agents, costs and benefits of global networks; and explore how world citizens preserve cultural specificity. Case studies on global health, human trafficking and labor migration illuminate the shaping influence of contemporary globalization on gender, race, ethnicity, and class. Develops cultural literacy through analysis of fiction and film. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.020"},{"code":"21L.024","title":"Literature and Existentialism","level":"U","description":"Studies major literary works associated with the 19th- and 20-century philosophical movement known as existentialism. Through close reading of these works, students explore how existentialist writers grappled with the question of death; the nature of free will; emotions like boredom, disgust, and radical doubt; and the fate of the individual in a modernity marked by war, illogic, and absurdity. Includes novels, short stories, and aphorisms by Sartre, Camus, Dostoevsky, Kafka, Hesse, Chopin, and Nietzsche; plays by Beckett and Stoppard; and films by Bergman, Tarkovsky, and others. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"56-114"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"2-147"},{"days":["R"],"start":"14:30","end":"16:00","room":"2-147"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.024"},{"code":"21L.027","title":"Children and Culture","level":"U","description":"Explores the relationship between children and the culture they inhabit in a particular time and place. Invites students to analyze in detail the image of childhood that emerges from many different media, including novels, children's literature, drama, film, television, dance, and popular song. Encourages students to take an interdisciplinary 'childhood studies' approach to youth culture that incorporates insights from literary and media studies, women's and gender studies, and the history and philosophy of childhood. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.027"},{"code":"21L.030","title":"A Random Walk Through Literature and Film","level":"U","description":"Focuses on the activity of walking in poems, novels, essays, film, and in everyday life. Combines reading and discussion with experiential learning. Considers broad historical transformations in the practice and representation of walking. Students conduct regular walks in the Greater Boston area on themes suggested by class material. In creative nonfiction assignments, students narrate their own walking experiences and engage imaginatively with the works under discussion. Authors and filmmakers vary but may include: Jane Austen, Henry David Thoreau, Virginia Woolf, Frank O'Hara, Richard Linklater, and Ava DuVernay. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.030"},{"code":"21L.032","title":"Afrofuturism, Magical Realism, and Other Otherwise Worlds","level":"U","description":"Examines Afrofuturism, magical realism, and other forms of the fantastic in literary texts, film, and other media. Through close reading and attention to historical, cultural, and sociopolitical context, students consider how these works reinterpret the past, diagnose modernity, and posit alternative futures. Particular attention given to the roles race, gender, class, and sexuality play within these radically imaginative worlds. Topics vary from term to term but might include work by Octavia Butler, Gabriel García Márquez, Samuel Delany, Toni Morrison, N.K. Jemisin, José María Arguedas, and Janelle Monáe. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.032"},{"code":"21L.315","title":"Prizewinners and Laureates","level":"U","description":"Examines particular texts and authors as having special merit and significance. Considers modern authors and filmmakers who have received such accolades as a Nobel Prize, a Pulitzer Prize, or an Oscar, as well as older authors who have been named as poets laureate, or honored by traditions of commentary, interpretation, and translation. Specific topics vary from term to term. May be repeated once for credit if the specific works studied differ. Confirm start and end dates on Literature website. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"19:00","end":"20:30","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.315"},{"code":"21L.325","title":"Small Wonders","level":"U","description":"Close examination of a coherent set of short texts and/or visual works. The selections may be the shorter works of one or more authors (poems, short stories or novellas), or short films and other visual media. Content varies from term to term. May be repeated once for credit if the works studied differ. Confirm start and end dates on Literature website.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"1-136"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.325"},{"code":"21L.435","title":"Literature and Film","level":"U","description":"Investigates relationships between the two media, including film adaptations as well as works linked by genre, topic, and style. Explores how artworks challenge and cross cultural, political, and aesthetic boundaries. Students taking graduate version complete additional assignments. May be repeated for credit with permission of instructor if content differs.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.435"},{"code":"21L.438","title":"Intersectional Feminist Memoir","level":"U","description":"Explores the memoir genre through a feminist intersectional lens, looking at the ways in which feminist writers ground personal experience within a complex understanding of race, gender, sexuality, class, ethnicity, immigration status/nationality, and dis/ablity. Gives particular attention to the relationships between the personal and the political; form and content; fact, truth, and imagination; self and community; trauma and healing; coming to voice and breaking silence. Readings include books by Audre Lorde, Janet Mock, Daisy Hernandez, Jessica Valenti, and Ariel Gore, and shorter pieces by Meena Alexander and Leah Lakshmi Piepzna-Samarasinha. Drawing on lessons taken from these works, students write a short memoir of their own.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.438"},{"code":"21L.474","title":"Representing Girlhood","level":"U","description":"Invites students to analyze cultural artifacts that represent girlhood from various eras and genres, including novels, children's literature, poetry, film, television, and popular music. Conceives girlhood in a broadly inclusive way, putting a range of materials — e.g., cultural artifacts that center Black, Jewish, Asian, and queer girls — in conversation with one another, by artists like Toni Morrison, Judy Blume, Andrea Wang, and Chappell Roan. Helps students build their oral presentation skills. Includes field trips to local museums or cultural events. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.474"},{"code":"21L.481","title":"HIV/AIDS in American Culture","level":"U","description":"Examines cultural responses to HIV/AIDS in the US during the first fifteen years of the epidemic, prior to the advent of highly active antiretroviral therapy. Students consider how sexuality, race, gender, class, and geography shaped the experience of HIV/AIDS and the cultural production surrounding it, as well as the legacy of this cultural production as it pertains to the communities most at risk today. Materials include mainstream press coverage, film, theater, television, popular music, comic books, literature, and visual art.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.481"},{"code":"21L.492","title":"Three Kingdoms: From History to Fiction, Comic, Film, and Game","level":"U","description":"Analyzing core chapters of the great Chinese epic novel, Three Kingdoms, and its adaptations across diverse media, considers what underlies the appeal of this classic narrative over the centuries. Through focus on historical events in the period 206 BC to AD 280, examines the representation of power, diplomacy, war, and strategy, and explores the tension among competing models of political authority and legitimacy. Covers basic elements of classical Chinese political and philosophical thought, and literary and cultural history. Final group project involves digital humanities tools. Readings in translation. Films and video in Chinese with English subtitles.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.492"},{"code":"21L.607","title":"Greek I","level":"U","description":"Introduces rudiments of ancient Greek - the language of Plato, Sophocles, Thucydides, and Euclid, and the basis for that of the New Testament - to students with little or no prior knowledge of the subject. Aimed at laying a foundation to begin reading ancient and/or medieval texts. Greek I and Greek II (21L.608) may be combined (after completion of both) to count as a single HASS-H.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.607"},{"code":"21L.608","title":"Greek II","level":"U","description":"Introductory Greek subject for students with some prior knowledge of basic grammar and vocabulary. Intended to refresh and enrich ability to read ancient and/or medieval literary and historical texts. May be taken independently of Greek I with permission of instructor. Greek I (21L.607)  and Greek II may be combined (after completion of both) to count as a single HASS-H.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.608"},{"code":"21L.613","title":"Latin Readings","level":"U","description":"Introduction to reading Latin literature in the original language. Provides a bridge between the study of Latin grammar and the reading of Latin authors. Improves knowledge of the language through careful examination of literary texts, focusing on prose and poetry in alternate years. Builds proficiency in reading Latin and develops appreciation for basic features of style and genre. Texts vary from term to term. May be repeated once for credit if content differs. 21L.613 and 21L.614, or two terms of 21L.613, may be combined by petition (after completion of both) to count as a single HASS-H.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.613"},{"code":"21L.614","title":"Advanced Latin Readings","level":"U","description":"Develops the ability to read and analyze Latin literary texts, focusing on prose and poetry in alternate years. Increases fluency in reading comprehension and recognition of stylistic, generic, and grammatical features. Texts vary from term to term. May be repeated once for credit if content differs. 21L.613 and 21L.614, or two terms of 21L.614, may be combined by petition (after completion of both) to count as a single HASS-H.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.614"},{"code":"21L.620","title":"Introduction to French Literature","level":"U","description":"A basic study of major French literary genres — poetry, drama, and fiction — and an introduction to methods of literary analysis. Authors include: Voltaire, Balzac, Sand, Baudelaire, Apollinaire, Camus, Sartre, Ionesco, Duras, and Tournier. Special attention devoted to the improvement of French language skills. Taught in French.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.620"},{"code":"21L.624","title":"Childhood and Youth in French and Francophone Cultures","level":"U","description":"Studies the transformation of childhood and youth since the 18th century in France, as well as the development of sentimentality within the family in a francophone context. Examines the personification of children, both as a source of inspiration for artistic creation and a political ideal aimed at protecting future generations. Considers various representations of childhood and youth in literature (e.g., Pagnol, Proust, Sarraute, Laye, Morgiévre), movies (e.g., Truffaut), and songs (e.g., Brel, Barbara). Taught in French.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.624"},{"code":"21L.630","title":"Understanding Contemporary French Politics","level":"U","description":"Examines French politics since 1958. Analyzes how politics has deeply influenced cultural and social life in France, including daily interactions. Questions public controversies and history's political cleavages, from the Algerian war to postcolonial issues, from the birth of the European construction to the Covid crisis. To explore French institutions and understand the impact of political issues in contemporary France, students 'run' for the French presidency by preparing historical notes, delivering speeches, participating in a first-round presidential debate, and submitting a final political statement. Taught in French. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"14N-313"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.630"},{"code":"21L.636","title":"Introduction to Contemporary Hispanic Literature and Film","level":"U","description":"Focuses on literary and cinematic production in 20th- and 21st-century Spain and Latin America with a particular emphasis on how social, cultural, political, and technological changes led to aesthetic innovations. Topics include the literature of politics, the avant-garde and subsequent literary boom, the radical aesthetic of the post-Franco era, and post-modern film and art. Materials include short stories, novels, poetry, song, and film. Conducted in Spanish.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.636"},{"code":"21L.703","title":"Studies in Drama","level":"U","description":"Intensive study of an important topic or period in drama. Close analysis of major plays, enriched by critical readings and attention to historical and theatrical contexts. Instruction and practice in oral and written communication through student presentations and research essays. Previously taught topics include: Renaissance Drama; Shakespeare with his Contemporaries; Oscar Wilde; and Stoppard and Company. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.703"},{"code":"21L.704","title":"Studies in Poetry","level":"U","description":"Intensive study of a body of poetry, raising questions of form, authorship, poetic influence, social context, and literary tradition. Instruction and practice in oral and written communication. Previously taught topics include: Does poetry Matter?, Poetry and the Science of Mind; Songs, Sonnets and the Story of English; Virgil, Spenser, Milton; and The Image: Poetry, Photography, and Technologies of Vision. Approved for credit in Women's and Gender Studies when content meets the requirements for subjects in that program. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.704"},{"code":"21L.705","title":"Major Authors","level":"U","description":"Close study of a limited group of writers. Instruction and practice in oral and written communication. Previously taught topics include John Milton and his Age, Chaucer, Herman Melville, Toni Morrison, and Oscar Wilde and the '90s. Approved for credit in Women's and Gender Studies when content meets the requirements for subjects in that program. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.705"},{"code":"21L.706","title":"Studies in Film","level":"U","description":"Intensive study of films from particular periods, genres, or directors, or films focusing on specific formal or theoretical problems. Instruction and practice in oral and written communication provided. Previous topics include The Contemporary Horror Film, Film Remixes, Film Narrative, Heroic Cinema, Color in Film and Hitchcock. Students taking graduate version complete different assignments. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.706"},{"code":"21L.903","title":"Topics in Ancient and Medieval Studies: Latin","level":"U","description":"Covers topics in Latin classes that are not provided in the regular subject offerings. Units vary depending on the number of class meetings, readings, and assignments. May be repeated for credit if topic differs.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/m21La.html#21L.903"},{"code":"21M.011","title":"Introduction to Western Music","level":"U","description":"Provides a broad overview of Western classical music from the Middle Ages to the 21st century. Designed to enhance the musical experience by developing listening skills and an understanding of diverse forms and genres. Major composers and works are placed in social and cultural contexts. Weekly lectures feature demonstrations by professional performers and introduce topics to be discussed in sections. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:30","end":"17:00","room":"4-270"}]},{"type":"Recitation","options":[{"days":["M","F"],"start":"14:00","end":"15:00","room":"4-152"},{"days":["M","F"],"start":"15:00","end":"16:00","room":"4-152"},{"days":["T","R"],"start":"15:00","end":"16:00","room":"4-152"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.011"},{"code":"21M.030","title":"Introduction to Musics of the World","level":"U","description":"An introduction to diverse musical traditions of the world. Music from a wide range of geographical areas is studied in terms of structure, performance practice, social use, aesthetics, and cross-cultural contact. Includes music making, live demonstrations by guest artists, and ethnographic research projects. Enrollment limited by lottery.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-158"},{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-158"},{"days":["T","R"],"start":"12:30","end":"14:00","room":"4-158"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.030"},{"code":"21M.051","title":"Fundamentals of Music","level":"U","description":"Introduces students to the rudiments of Western music through oral, aural, and written practice utilizing rhythm, melody, intervals, scales, chords, and western staff notation. Individual skills are addressed through a variety of approaches, including the required piano and sight singing labs. Intended for students with little to no prior experience reading music or performing. Not open to students who have completed 21M.150, 21M.151, 21M.301, 21M.302, or are proficient in reading music. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-158"},{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-162"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.051"},{"code":"21M.053","title":"Rhythms of the World","level":"U","description":"Experiential, fully-embodied exploration into the fundamentals of music through the lens of largely non-Western, aural music cultures. From Bali to Ghana, Cuba to India, Zimbabwe to Andalucía, and through popular musics across the globe, students think about, talk about, and make music in new ways. Examines some of the basic concepts of music — structure, melody-making, meter, rhythm, interaction, movement, etc. — studying their diverse incarnations in different music cultures and encouraging a breadth of perspective and engagement. Students engage with a diverse blend of musical practices through music-making, in-depth discussion, listening and analysis, and creative composition. No musical experience required. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"4-162"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.053"},{"code":"21M.065","title":"Introduction to Musical Composition","level":"U","description":"Project-oriented class, beginning with a series of guided micro-compositions and culminating in a final composition which is rehearsed, workshopped, and performed. Assignments focus on specific musical parameters (melody and mode, rhythm and meter, form and structure), composing for film and video games, creating beats and grooves, and using microphones and digital audio workstations to create sound sculptures. Listening and discussion assignments present music from a wide range of genres and styles. Students create several complete pieces, sharpen their notation and musicianship skills, and learn the basics of sequencing, recording, and audio editing. Familiarity with western music notation is strongly encouraged; previous compositional and/or arranging experience is welcome but not required. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"4-162"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.065"},{"code":"21M.080","title":"Introduction to Music Technology","level":"U","description":"Investigates how technology is used in the analysis, modeling, synthesis and composition of music, and its contribution to the artistic production practice. With an eye towards historical context as well as modern usage, topics include the physics of sound, digital representations of music, the Digital Audio Workstation (DAW), analog and digital synthesis techniques, MIDI and sequencing, electronic instrument design, notation software, generative music systems, and computational analysis of music. Weekly assignments focus on both theory and practice, requiring technical proficiency, creative output, and aesthetic consideration. Students taking graduate version complete different assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:30","end":"14:00","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.080"},{"code":"21M.139","title":"Moments in Music: Composition B","level":"U","description":"Practice in a particular compositional technique not normally covered in the Harmony and Counterpoint or Musical Composition sequences. Possible topics include Renaissance counterpoint, fugue, ragtime, or indeterminacy. May be repeated once for credit if content differs. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-158"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.139"},{"code":"21M.150","title":"Accelerated Fundamentals of Music","level":"U","description":"Accelerated half-semester study of the fundamentals of Western music. Requires ability to read Western staff notation in at least one clef. Coverage includes intervals, triads, major and minor keys, basic musical analysis over a variety of idioms in Western music. Also emphasizes developing the ear, voice, and keyboard skills. Not open to students who have completed or are enrolled in 21M.051, 21M.151, 21M.301, or 21M.302. Subject content is identical to 21M.151: 21M.150 is offered first half of term; 21M.151 is offered second half of term or during IAP. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-158"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.150"},{"code":"21M.271","title":"Symphony and Concerto","level":"U","description":"Explores the style, form, and history of approximately two dozen pieces of canonical symphonic repertoire. Students write short reviews of musicological articles on the rich cultural history of selected works and complete one project about classical music in contemporary society. Basic score-reading ability required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W18-4311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.271"},{"code":"21M.284","title":"Film Music","level":"U","description":"Provides a conceptual foundation and methodology for the study of music created for various types of (mainly) narrative films, from the medium's origins in the early twentieth century to the present. Close attention to select influential scores by composers active in Hollywood from the 1940s to the 1990s (e.g., Max Steiner, Bernard Herrmann, Quincy Jones, John Williams). Those works are juxtaposed with landmarks of alternative film and musical styles from other countries and centers of production. Subsidiary topics include the history and challenges of live musical accompaniment to silent films, and the evolution of recording and sound-editing technologies from the studio era to the global present. Students taking the graduate version complete different assignments. Some background in the study of film and/or music is desirable, but not a prerequisite.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-364"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.284"},{"code":"21M.294","title":"Popular Musics of the World","level":"U","description":"Examines select popular music genres from around the world through audio-visual materials, reading assignments, and classroom discussion. Considers issues of globalization, appropriation, and the impact of social media. Case studies include bhangra, Latin pop, Afropop, reggae, Kpop, and global hip-hop. Limited to 25; preference to Music majors, minors, concentrators. Admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"4-364"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.294"},{"code":"21M.295","title":"American Popular Music","level":"U","description":"Surveys the development of popular music in the US, and in a cross-cultural milieu, relative to the history and sociology of the last two hundred years. Examines the mixture that characterizes modern music, and how it reflects many rich traditions and styles (minstrelsy, Tin Pan Alley, blues, country, rock, soul, rap, techno, etc.). Provides a background for understanding the musical vocabulary of current popular music styles. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"4-364"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.295"},{"code":"21M.298","title":"The Beat of Brazil: Language and Society Through Music","level":"U","description":"Presents an overview of Brazilian history, art, and culture from the late 19th century to the present day. Topics covered are woven into the larger theme of popular Brazilian music, and include the Modern Art Week of 1922, Candido Portinari's paintings, the Tropicalist art movement, and the role of artists and intellectuals during and after the military dictatorship. Identifies and distinguishes the main Brazilian musical styles, connecting them to specific historical periods and events, discussing how they reflect different notions of identity, and analyzing cultural production from a transnational perspective. Practice in listening, speaking, reading, and writing is provided, with strong emphasis on developing critical thinking. Taught in Portuguese. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"14N-221"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.298"},{"code":"21M.299","title":"Studies in Global Musics","level":"U","description":"Studies of selected topics in ethnomusicology (the study of music in culture). Topics vary. Examples include the social lives of musical instruments, music and storytelling, fieldwork methodologies, music and politics, and theories of global musics. May be repeated for credit with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"4-158"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.299"},{"code":"21M.301","title":"Harmony and Counterpoint I","level":"U","description":"Explores Western diatonic music through regular composition and analysis assignments. Engages a broad range of historical periods, traditions, and individuals. Topics include rhythm and meter, harmony and counterpoint within a single key, and a brief overview of form and modulation. Individual skills are addressed through a variety of approaches, including the required piano and sight singing labs. Local musicians perform final composition projects. Students should be proficient in reading Western staff notation in at least one clef and have experience with key signatures and scales. Students taking the graduate version complete additional assignments. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"4-162"},{"days":["T","R"],"start":"14:00","end":"15:30","room":"4-158"},{"days":["T","R"],"start":"15:30","end":"17:00","room":"4-158"}]},{"type":"Lab","options":[{"days":["F"],"start":"14:00","end":"15:30","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.301"},{"code":"21M.302","title":"Harmony and Counterpoint II","level":"U","description":"A continuation of 21M.301, including chromatic harmony and modulation, a more extensive composition project, keyboard laboratory, and musicianship laboratory. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-152"},{"days":["M","W"],"start":"12:30","end":"14:00","room":"4-162"}]},{"type":"Lab","options":[{"days":["R"],"start":"15:30","end":"17:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.302"},{"code":"21M.303","title":"Writing in Tonal Forms I","level":"U","description":"Written and analytic exercises based on 18th- and 19th-century small forms and harmonic practice found in music such as the chorale preludes of Bach; minuets and trios of Haydn, Mozart, and Beethoven; and the songs and character pieces of Schubert and Schumann. Musicianship laboratory is required. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-162"}]},{"type":"Lab","options":[{"days":["R"],"start":"15:30","end":"17:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.303"},{"code":"21M.310","title":"Techniques of 20th-Century Composition","level":"U","description":"Students complete written and analytical exercises based on compositional forms and practices from the first half of the 20th century. Areas covered include compositions based upon artificial scales and modes, as in Debussy, Bartok, and Stravinsky; compositions based on atonal pitch organizations, as with Schoenberg and Webern; compositions based on rhythmic process, timbral exploration, and/or non-Western influences. Basic instrumentation taught and compositions performed in class. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-162"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.310"},{"code":"21M.340","title":"Jazz Harmony and Arranging","level":"U","description":"Basic harmony and theory of mainstream jazz and blues; includes required listening in jazz, writing and analysis work, and two full-scale arrangements. Serves as preparation for more advanced work in jazz with application to rock and pop music. Performance of student arrangements. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"4-152"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.340"},{"code":"21M.361","title":"Electronic Music Composition I","level":"U","description":"Students develop basic skills in composition through weekly assignments focusing on contemporary computer music composition practices. Topics may include: audio sampling, digital signal processing, algorithmic and generative processes, virtual instruments,  electronic music history, and emerging practices. Assignments utilize tools such as digital audio workstations, analog synthesizers, music programming environments, MIDI programming, mixing, and recording studio techniques. Students critique each other's work and respond to recordings drawn from sound art, experimental electronica, conventional and non-conventional classical electronic works, and popular music. Students taking graduate version complete different assignments. Limited to 15 per section; preference to Music Technology graduate students, Music majors, minors, and concentrators.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.361"},{"code":"21M.365","title":"DJ History, Technique, and Technology","level":"U","description":"Students explore a chosen contemporary or historical dance scene from around the world. Lectures examine the evolution of the craft and technologies of the DJ. Presents foundational practices of live DJ mixing; practice equipment is accessible to teams of students. Assignments include writing a report analyzing a book on DJ history or technique, producing a complete mix, and participation in an end-of-term performance. No prior experience is necessary, but students must sustain interest in some form of popular dance music, broadly defined. Graduate students complete additional assignments. Limited to 24.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.365"},{"code":"21M.369","title":"Studies in Music Technology","level":"U","description":"Explores various technologies in relation to musical analysis, composition, performance, culture, and quantitative methods. Topics vary each term and may include development and impact on society, generative and algorithmic music, recording techniques or procedural sound design. May involve hands-on components such as laptop music ensemble, new instrument building, or comparing the theory and practice of audio recording. Students taking graduate version complete different assignments. Limited to 16.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"W97-269"}]},{"type":"Lab","options":[{"days":["F"],"start":"12:00","end":"13:30","room":"W18-4311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.369"},{"code":"21M.370","title":"Digital Instrument Design","level":"U","description":"Covers aesthetic and technical challenges in the creation of physical interfaces for musical performance. will engage in the design and creation of musical interfaces, and learn how to incorporate new technologies in their artistic practice. Topics covered include user experience design for artistic performance, musical human-computer interaction (HCI), hardware and software standards for digital musical systems, embedded programming and sound synthesis, analog and digital sensors, rapid prototyping and digital manufacturing, and creating performance practices around custom hardware. Students design and build their own digital musical instrument, and present a performance with the instrument as their final project. Students taking graduate version complete different assignments. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.370"},{"code":"21M.385","title":"Interactive Music Systems","level":"U","description":"Explores audio synthesis, musical structure, human computer interaction (HCI), and visual presentation for the creation of interactive musical experiences. Topics include audio synthesis; mixing and looping; MIDI sequencing; generative composition; motion sensors; music games; and graphics for UI, visualization, and aesthetics. Includes weekly programming assignments in python. Teams build an original, dynamic, and engaging interactive music system for their final project. Students taking graduate version complete different assignments. Limited to 36.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.385"},{"code":"21M.389","title":"Studies in Advanced Music Technology and Computation","level":"U","description":"Studies of a selected topic in music technology requiring substantial prior knowledge of music studies, music technology, and computation. Topics vary. Examples include: computational modeling of music, artificial intelligence and musical creativity, digital signal processing for music, and real-time Internet musical collaboration. Students must have taken at least one prior music technology subject prior to this one. May be repeated for credit with permission of instructor. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.389"},{"code":"21M.401","title":"MIT Concert Choir","level":"U","description":"Rehearsals and performance of primarily large-scale works for chorus, soloists, and orchestra--from the Passions and Masses of J. S. Bach to oratorios of our own time. Open to graduate and undergraduate students by audition.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"19:00","end":"21:30","room":"W18-1102"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.401"},{"code":"21M.405","title":"MIT Chamber Chorus","level":"U","description":"Rehearsal and performance of choral repertoire for small chorus, involving literature from the Renaissance to contemporary periods. Students taking graduate version complete additional assignments. Limited to 32 by audition.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"W18-1102"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.405"},{"code":"21M.421","title":"MIT Symphony","level":"U","description":"Rehearsals prepare works for concerts and recordings. Analyses of musical style, structure, and performance practice are integrated into rehearsals as a means of enriching musical conception and the approach to performance. Likewise, additional scores of particular structural or stylistic interest are read whenever time permits. Admission by audition.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"19:30","end":"22:00","room":"KRESGE"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.421"},{"code":"21M.423","title":"Conducting and Score-Reading","level":"U","description":"Introduces ensemble conducting as a technical and artistic discipline.  Incorporates ear training, score-reading skills and analysis, rehearsal technique, and studies of various philosophies.  Attendance of rehearsals and specific concerts required.  Opportunities include conducting students, professional musicians, and MIT Symphony Orchestra (when possible).  Instrumental proficiency required, although vocalists with keyboard abilities will be accepted.  May be repeated once for credit with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"W18-4311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.423"},{"code":"21M.426","title":"MIT Wind Ensemble","level":"U","description":"Designed for advanced instrumentalists who are committed to the analysis, performance, and recording of woodwind, brass, and percussion literature from the Renaissance through the 21st century. The repertoire consists primarily of music for small and large wind ensembles. May include ensemble music from Gabrieli to Grainger, Schuller, Mozart, Dvorak, and various mixed media including strings. Performance of newly commissioned works. Opportunities for solo work and work with recognized professional artists and composers. Admission by audition.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"19:00","end":"21:30","room":"KRESGE"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.426"},{"code":"21M.442","title":"MIT Festival Jazz Ensemble","level":"U","description":"Designed for instrumentalists dedicated to the analysis, performance, and recording of traditional and contemporary jazz ensemble compositions. Instrumentation includes saxophones, trumpets, trombones, piano, guitar or vibraphone, bass, percussion and occasionally french horn, double reeds, and strings. Provides opportunities to work with professional jazz artists and perform commissioned works by recognized jazz composers. Experience in improvisation preferred but not required. Admission by audition.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"17:00","end":"19:30","room":"14W-111"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.442"},{"code":"21M.450","title":"MIT Balinese Gamelan","level":"U","description":"A performing ensemble dedicated to the traditional music of Bali. Members of the ensemble study structures and techniques used on various gamelan instruments — such as gangsa (ancient bronze metallophones), suling (Balinese bamboo flute), reyong (bronze pots), gongs, and drums — and learn to perform gamelan pieces. Culminates in a performance. No previous experience required.","groups":[{"type":"Lab","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"W18-1202"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.450"},{"code":"21M.460","title":"MIT Senegalese Drum Ensemble","level":"U","description":"A performance ensemble focusing on the sabar drumming tradition of Senegal, West Africa. Study and rehearse Senegalese drumming techniques and spoken word. Perform in conjunction with MIT Rambax drumming group. No previous experience necessary, but prior enrollment in 21M.030 or 21M.293 strongly recommended. Limited to 30 by audition.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"20:30","end":"22:00","room":"W18-1202"},{"days":["M","R"],"start":"19:00","end":"20:30","room":"W18-1202"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.460"},{"code":"21M.470","title":"MIT Laptop Ensemble","level":"U","description":"The MIT Laptop Ensemble is a forum for the exploration of emerging digital musical practices, giving ensemble members hands-on experience with compositional and performance strategies based on current research. Concerts by the ensemble include repertoire drawn both from historical electronic and computer music compositions, as well as new compositions by invited composers. Also includes opportunities for ensemble members to compose for and conduct the ensemble. Weekly rehearsals focus on concepts drawn from a variety of 20th- and 21st-century practices, including experimental and improvised music, telematic performance, gestural controllers, multimedia performance, live coding, and interactive music systems. No previous experience required. Students taking graduate version complete different assignments. Admission by audition.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.470"},{"code":"21M.480","title":"Advanced Music Performance","level":"U","description":"Designed for students who demonstrate considerable technical and musical skills in an instrument or voice type, and wish to further their training through private musical study and performance. Students take weekly private lessons, attend masterclasses, give solo or group performances, and participate in an MTA ensemble. Students taking graduate version complete different assignments. Full program information, including lesson fees, scholarships, and auditions, are available on the MTA Emerson/Harris Program webpage. Open to full-time MIT students only; full year commitment required. Admission is restricted to Emerson/Harris Scholars and by audition only.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:00","end":"19:00","room":"14W-111"},{"days":["W"],"start":"17:00","end":"19:00","room":"W18-4305"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.480"},{"code":"21M.500","title":"Advanced Seminar in Music","level":"U","description":"Seminar that develops analytic and research skills in music history/culture or theory/composition. Topics vary, but are organized around a particular methodology, musical topic, or collection of works, that allow for application to a variety of interests and genres. Strong emphasis on student presentations, discussion, and a substantial writing project. May be repeated for credit with permission from instructor. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"4-158"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.500"},{"code":"21M.506","title":"MIT Chamber Chorus","level":"G","description":"Rehearsal and performance of choral repertoire for small chorus, involving literature from the Renaissance to contemporary periods. Students taking graduate version complete additional assignments. Limited to 32 by audition.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"W18-1102"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.506"},{"code":"21M.510","title":"Techniques of 20th-Century Composition","level":"G","description":"Students complete written and analytical exercises based on compositional forms and practices from the first half of the 20th century. Areas covered include compositions based upon artificial scales and modes, as in Debussy, Bartok, and Stravinsky; compositions based on atonal pitch organizations, as with Schoenberg and Webern; compositions based on rhythmic process, timbral exploration, and/or non-Western influences. Basic instrumentation taught and compositions performed in class. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-162"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.510"},{"code":"21M.512","title":"Advanced Music Performance","level":"G","description":"Designed for students who demonstrate considerable technical and musical skills in an instrument or voice type, and wish to further their training through private musical study and performance. Students take weekly private lessons, attend masterclasses, give solo or group performances, and participate in an MTA ensemble. Students taking graduate version complete different assignments. Full program information, including lesson fees, scholarships, and auditions, are available on the MTA Emerson/Harris Program webpage. Open to full-time MIT students only; full year commitment required. Admission is restricted to Emerson/Harris Scholars and by audition only.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:00","end":"19:00","room":"14W-111"},{"days":["W"],"start":"17:00","end":"19:00","room":"W18-4305"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.512"},{"code":"21M.517","title":"MIT Laptop Ensemble","level":"G","description":"The MIT Laptop Ensemble is a forum for the exploration of emerging digital musical practices, giving ensemble members hands-on experience with compositional and performance strategies based on current research. Concerts by the ensemble include repertoire drawn both from historical electronic and computer music compositions, as well as new compositions by invited composers. Also includes opportunities for ensemble members to compose for and conduct the ensemble. Weekly rehearsals focus on concepts drawn from a variety of 20th- and 21st-century practices, including experimental and improvised music, telematic performance, gestural controllers, multimedia performance, live coding, and interactive music systems. No previous experience required. Students taking graduate version complete different assignments. Admission by audition.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.517"},{"code":"21M.526","title":"Advanced Seminar in Music","level":"G","description":"Seminar that develops analytic and research skills in music history/culture or theory/composition. Topics vary, but are organized around a particular methodology, musical topic, or collection of works, that allow for application to a variety of interests and genres. Strong emphasis on student presentations, discussion, and a substantial writing project. May be repeated for credit with permission from instructor. Student taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"4-158"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.526"},{"code":"21M.560","title":"Introduction to Music Technology","level":"G","description":"Investigates how technology is used in the analysis, modeling, synthesis and composition of music, and its contribution to the artistic production practice. With an eye towards historical context as well as modern usage, topics include the physics of sound, digital representations of music, the Digital Audio Workstation (DAW), analog and digital synthesis techniques, MIDI and sequencing, electronic instrument design, notation software, generative music systems, and computational analysis of music. Weekly assignments focus on both theory and practice, requiring technical proficiency, creative output, and aesthetic consideration. Students taking graduate version complete different assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:30","end":"14:00","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.560"},{"code":"21M.561","title":"Electronic Music Composition I","level":"G","description":"Students develop basic skills in composition through weekly assignments focusing on contemporary computer music composition practices. Topics may include: audio sampling, digital signal processing, algorithmic and generative processes, virtual instruments,  electronic music history, and emerging practices. Assignments utilize tools such as digital audio workstations, analog synthesizers, music programming environments, MIDI programming, mixing, and recording studio techniques. Students critique each other's work and respond to recordings drawn from sound art, experimental electronica, conventional and non-conventional classical electronic works, and popular music. Students taking graduate version complete different assignments. Limited to 15 per section; preference to Music Technology graduate students, Music majors, minors, and concentrators.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.561"},{"code":"21M.569","title":"Studies in Music Technology","level":"G","description":"Explores various technologies in relation to musical analysis, composition, performance, culture, and quantitative methods. Topics vary each term and may include development and impact on society, generative and algorithmic music, recording techniques or procedural sound design. May involve hands-on components such as laptop music ensemble, new instrument building, or comparing the theory and practice of audio recording. Students taking graduate version complete different assignments. Limited to 16.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"W97-269"}]},{"type":"Lab","options":[{"days":["F"],"start":"12:00","end":"13:30","room":"W18-4311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.569"},{"code":"21M.570","title":"Digital Instrument Design","level":"G","description":"Covers aesthetic and technical challenges in the creation of physical interfaces for musical performance. will engage in the design and creation of musical interfaces, and learn how to incorporate new technologies in their artistic practice. Topics covered include user experience design for artistic performance, musical human-computer interaction (HCI), hardware and software standards for digital musical systems, embedded programming and sound synthesis, analog and digital sensors, rapid prototyping and digital manufacturing, and creating performance practices around custom hardware. Students design and build their own digital musical instrument, and present a performance with the instrument as their final project. Students taking graduate version complete different assignments. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"W18-1311"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.570"},{"code":"21M.585","title":"Interactive Music Systems","level":"G","description":"Explores audio synthesis, musical structure, human computer interaction (HCI), and visual presentation for the creation of interactive musical experiences. Topics include audio synthesis; mixing and looping; MIDI sequencing; generative composition; motion sensors; music games; and graphics for UI, visualization, and aesthetics. Includes weekly programming assignments in python. Teams build an original, dynamic, and engaging interactive music system for their final project. Students taking graduate version complete different assignments. Limited to 36.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.585"},{"code":"21M.589","title":"Studies in Advanced Music Technology and Computation","level":"G","description":"Studies of a selected topic in music technology requiring substantial prior knowledge of music studies, music technology, and computation. Topics vary. Examples include computational modeling of music, artificial intelligence and musical creativity, digital signal processing for music, and real-time Internet musical collaboration. Students must have taken at least one prior music technology subject prior to this one. May be repeated for credit with permission of instructor. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.589"},{"code":"21M.595","title":"Music Technology And Computation Graduate Seminar","level":"G","description":"Development of a major independent project in music technology and computation. Includes group discussions, presentations of work-in-progress, and readings related to planning, contextualizing, and effective communication. Occasional guest speakers from industry, academia, or artistic practice present their work and lead discussions. Covers development processes like ideation, prototyping, scheduling, deliverables, and evaluation.  Restricted to SM and MASc in Music Technology and Computation students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:30","end":"17:00","room":"W18-2310"}]}],"url":"http://student.mit.edu/catalog/m21Ma.html#21M.595"},{"code":"21M.600","title":"Introduction to Acting","level":"U","description":"Explores the actor's tools: body, voice, mind, imagination, and the essential self. Through studio exercises, students address issues of honesty and creativity in the theatrical moment, and begin to have a sense of their strengths and limitations as communicating theatrical artists. Provides an opportunity for students to discover their relationship to 'the other' in the acting partner, the group, the environment, and the audience. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"13:00","room":"W97-269"},{"days":["M","W"],"start":"13:00","end":"15:00","room":"W97-269"},{"days":["M","W"],"start":"13:00","end":"15:00","room":"W97-160"},{"days":["M","W"],"start":"15:00","end":"17:00","room":"W97-160"},{"days":["T","R"],"start":"11:00","end":"13:00","room":"W97-160"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"W97-269"},{"days":["T","R"],"start":"15:00","end":"17:00","room":"W97-269"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.600"},{"code":"21M.601","title":"Drawing for Designers","level":"U","description":"Explores drawing as a fundamental component of the design process. In-class drawing exercises focus on developing the hand-to-eye relationship and pre-visualization skills essential to any designer. Studies the use drawing as a route to understanding space and form and achieving accuracy through expression. By drawing figures, landscapes and/or still life compositions in a variety of media, students investigate the figure/ground relationship while dealing with tone, line, and composition, which are all requisite elements of design. Provides exposure to designers who have used drawing as a central component of their work. Students create a portfolio that includes in-class drawings, studies done outside of class, and one research-based written project. Lab fee required.  Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-261"},{"days":["T"],"start":"19:00","end":"22:00","room":"W97-261"},{"days":["W"],"start":"19:00","end":"22:00","room":"W97-261"},{"days":["R"],"start":"14:00","end":"17:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.601"},{"code":"21M.604","title":"Playwriting Fundamentals","level":"U","description":"Introduces the craft of writing for the theater, with special attention to the basics of dramatic structure. Through weekly assignments and in-class exercises, students explore character, conflict, language and plasticity in scenes and short plays. In workshop format, students present individual work for feedback and heavily revise their work based on that response. Readings include a variety of plays.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-267"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.604"},{"code":"21M.605","title":"Voice and Speech for the Actor","level":"U","description":"Concentrates upon freeing the natural voice through awareness of physical, vocal and, at times, emotional habits and the willingness and desire to experience change. Teaches progression of contemporary approaches to voice through in-class vocal exercises. Students use sonnets or poems as vehicles to explore the components of language and the need to communicate and reveal oneself through the voice. Designed for students interested in theater or developing their voices for presentations and professional speaking. Limited to 18; preference to Theater majors, minors, and concentrators who have pre-registered.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"50-201"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"50-201"},{"days":["T","R"],"start":"15:00","end":"17:00","room":"50-201"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.605"},{"code":"21M.608","title":"Screenwriting","level":"U","description":"Explores the fundamentals of screenplay writing.  Presents skills to create compelling characters and stories in different dramatic genres (comedy, drama). In addition to their own writing, students read a selection of screenplays and watch short films that form the basis of class discussion early in the term.  Class is modeled on a professional development workshop in which participants, over the course of the term, write a short screenplay, including a final draft.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W97-267"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.608"},{"code":"21M.609","title":"Introduction to Drama","level":"U","description":"A study of the history of theater art and practice from its origins to the modern period, including its roles in non-Western cultures. Special attention to the relationship between the literary and performative dimensions of drama, and the relationship between drama and its cultural context. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14N-217"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.609"},{"code":"21M.622","title":"Physical Improvisation: Scores and Structures","level":"U","description":"Explores physical improvisation in dance/theater from a variety of task-based, conceptual vantage points. Focuses on conceptual frameworks for generating intensely physical dramatic actions and dances that unlock the students' creativity. Investigates topics such as narrative, how stories and scenarios can elicit movement and emotionally resonant physical interaction; visual composition, creating movement and actions on stage from an imagistic starting point; and hypothetical worlds, movement based on the creation of rules for alternate worlds (e.g., strange, indigenous time, strange evolution). Explores solos, duets, trios, and larger ensemble improvisations. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"17:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.622"},{"code":"21M.623","title":"Physical Improvisation: Bodies in Motion","level":"U","description":"Explores the realities of the body in space and motion - interacting with gravity, momentum, inertia, alignment, negative space, one's imagination, one's body, other bodies, the present room and rooms from memory, geometry, stillness, and more. By releasing tension and abandoning the notion of pre-planning, students experience a natural, spontaneous flow of movement, opening themselves up to, and diving into, whatever might happen. Develops alertness in order to work in an energetic state of physical disorientation, self-correcting what doesn't work and reinforcing what does on the spot, discovering physical/emotional truths and shared moments that leave students aware, centered, incredibly present, and sharply alive. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"13:00","room":"W97-162"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"W97-160"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.623"},{"code":"21M.624","title":"Acting with the Camera","level":"U","description":"Studio workshop explores the discipline of acting for the camera through in-class exercises that focus on the creative challenges inherent to both filming and being filmed. Investigates the performer in the history of cinema, television, and multimedia stage performance through readings, screenings, and experimentation with the theory and practice of performing for and with the camera. Culminates in student-written, edited, directed, and acted short films. Instruction in written and oral communication provided. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"17:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.624"},{"code":"21M.645","title":"Motion Theater","level":"U","description":"Examines the theatrical event from the perspective of composition in a performance workshop. Studio exercises address the process of developing a theatrical work through an internalized understanding of compositional principles in theater. Examines physical action in time and space. Includes outside readings, videos, short essays, and in-class discussions. Provides the performer, director, choreographer, designer or writer opportunities to engage with large and small group ensembles in creation of theatrical events. Topics include image, motion, shape, repetition, gesture, and spatial relationship. Preference to majors, minors, concentrators. Admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.645"},{"code":"21M.690","title":"Sport as Performance","level":"U","description":"Seminar investigates the aesthetics of sport as theatrical performance and explores the performance of race, gender, class, nation, and sexuality in sport. Readings drawn from theatre/performance studies, anthropology, sociology, ethnic studies, gender studies, history, and kinesiology. Topics include barnstorming, Olympics, Title IX, Native American mascots, and a variety of sports ranging from football to figure skating. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.690"},{"code":"21M.702","title":"Live Solo Performance: Monodrama and Composition","level":"U","description":"Studies the theatrical canon of monodramas and solo performances to hone individual acting skills. Goes on to explore each student's original artistic voice by presenting strategies in composing and staging work, thus introducing them to experiments with performing the self in society. Each student creates their own original performance piece by the end of the term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.702"},{"code":"21M.710","title":"Script Analysis","level":"U","description":"Focuses on reading a play's script critically and theatrically, with a view to mounting a coherent production. Through careful, intensive analysis of a variety of plays from different periods and aesthetics, a pattern emerges for discerning what options exist for interpreting a script from the distinct perspectives of the playwright, the actor, the designer, and the director. Students discuss the consequences of those options for production.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W97-269"},{"days":["W"],"start":"19:00","end":"22:00","room":"W97-267"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.710"},{"code":"21M.712","title":"Choreography: Making Dances","level":"U","description":"Laboratory-style class explores and invents techniques used to create dances. Students practice techniques focused on how and where to begin making a dance - sampling some of the endless ways to start a process, such as from the body, an idea, text, or a song - and then how to build up from there. Students make dances that are more than just a collection of moves, but events that do something, say something, or ask something. Builds a clear understanding of how a dance has an arc, a clear beginning, middle, and end, so that by doing it or watching it, both participants and audience end up somewhere new. Develops an understating of, and facility with, a wide variety of topics used to explore, start and generate movement, dance and performative events involving bodies moving through space. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.712"},{"code":"21M.716","title":"Play Translation and Cultural Transmission","level":"U","description":"Through reading texts about translation and by doing an independent project, students develop significant skills in translation theory and practice, culminating in a public staged reading of their translations. Each student chooses a dramatic text from a non-English language and translates a scene during the semester. Readings include topics such as globalization, adaptation, gender in translation, and postcolonial approaches to translation.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.716"},{"code":"21M.733","title":"Set Design","level":"U","description":"Investigates the creation of set design for live performance. Students develop designs related to current production projects at MIT. Focuses on developing the designer's communication tools, particularly in the areas of visual research, 3-D digital model making, and design presentation. Examines the relationship of set design to theater architecture, emerging media technologies and dramaturgies of the 20th and 21st centuries. In addition to creating their own designs, students research, write about, and present the work and practice of a set designer. Lab fee required.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.733"},{"code":"21M.737","title":"Interactive Design and Projection for Live Performance","level":"U","description":"Studies design, history, artistic purposes, and programming techniques involved in the development of interactive performance design systems for controlling video projection, media, and lighting for live performances. Includes readings, viewings of historical and contemporary works, and in class-practice and performance. Students use motion-sensing input devices, such as the Kinect, infrared-light tracking, accelerometers, live video, and generative graphics, to create interactive design systems.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.737"},{"code":"21M.747","title":"Talking and Dancing","level":"U","description":"Interdisciplinary dance theater studio invites students to investigate the spaces between dance and theater. Students engage in an array of acting and dance techniques to generate text from movement and movement from text. In-studio exercises examine the process of melding the expressive languages of words with languages of the body. Students use existing texts and compose original texts in the development of solo, duet, and ensemble projects. Explores the process of seeing and providing peer feedback to further expand the process of revision. Readings, short writings, video viewings, and guest lectures provide multiple avenues of understanding and illumine differing ways of making. Culminates with an opportunity for students to refine, develop, and share their projects in performance.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"W97-269"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.747"},{"code":"21M.784","title":"Producing Podcasts","level":"U","description":"Students write and produce a pilot episode of a narrative podcast (about fifteen minutes in length); sources come from interviews or research that students conduct. At the start of the term, students pitch possible stories. Discussions of selected episodes of narrative podcasts such as Serial, Homecoming, and This American Life. Introduces the basics of podcast recording with a primer on using Logic Pro X and hardware like the Apogee Duet. Students record and edit a rough draft of their podcast using provided portable recording studio kits. Podcasts shared with the larger MIT community at the Podcast Listening Room at the end of term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-269"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.784"},{"code":"21M.812","title":"Theater Arts Production","level":"U","description":"No textbook information available","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-165"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.812"},{"code":"21M.822","title":"Theater Arts Production","level":"G","description":"Production studio invites students to join Theater Arts faculty and staff in the development of a fully-staged production for an invited audience in MIT's new laboratory for the performing arts. Students are immersed in the collaboration as performers, designers, writers, choreographers and technicians. Weekly rehearsals, design labs, and workshops introduce students to an array of rehearsal and performance techniques over the course of the semester. Culminating in a public performance, students at all levels of experience are encouraged to join. Each semester evolves a different project which may include community-driven interventions, classical or contemporary plays, devised works, screenplays, musicals or other live performance events.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-165"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.822"},{"code":"21M.830","title":"Acting: Techniques and Style","level":"U","description":"Refines the student actor's use of the language of the stage with work on text and physical presentation. Explores issues of style, including the understanding and honoring, in performance, of the specific requirements from several different periods of the Western theatrical tradition. Periods may differ from term to term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"W97-269"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.830"},{"code":"21M.835","title":"Acting: Techniques and Style","level":"G","description":"Refines the student actor's use of the language of the stage with work on text and physical presentation. Explores issues of style, including the understanding and honoring, in performance, of the specific requirements from several different periods of the Western theatrical tradition. Periods may differ from term to term. Students taking graduate versions complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"W97-269"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.835"},{"code":"21M.861","title":"Topics in Performance Technique","level":"U","description":"Explores elements of technique in a variety of performance disciplines.  Topics vary from term to term; may be taught by visiting faculty. May be repeated for credit if content differs.  Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.861"},{"code":"21M.862","title":"Topics in Performance Practice","level":"U","description":"Class explores elements of performance in a studio setting. Topics vary from term to term; may be taught by visiting faculty. May be repeated for credit if content differs. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Mb.html#21M.862"},{"code":"21T.001","title":"Fundamentals of Stage Technology","level":"U","description":"Explores the tools, techniques, and technologies that bring live performances to life. Through practical exercises, guest speakers, and field trips, provides a behind-the-scenes look at the different areas of stage production including carpentry, lighting, sound, video, rigging, and stage management. Explores stagecraft in action by touring local theaters and scene shops and attending the department's student production as well as at least one professional production in the Boston area. All tickets are provided at no additional cost. Subject can count toward the 6-unit discovery-focused credit limit for first-year students. Enrollment limited to 30.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.001"},{"code":"21T.100","title":"Theater Arts Production","level":"U","description":"No textbook information available","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"W97-160"}]},{"type":"Lab","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.100"},{"code":"21T.101","title":"Introduction to Acting","level":"U","description":"Explores the actor's dramatic instincts with body, voice, imagination, language, and action. Studio exercises foster creative curiosity, improvisation, collaboration, and a sense of kinesthetic and spatial awareness. Develops communication skills and offers varied approaches to relating with self, ensemble, character, dramatic material, and audience. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"11:00","room":"W97-160"},{"days":["M","W"],"start":"11:00","end":"13:00","room":"50-201"},{"days":["M","W"],"start":"13:00","end":"15:00","room":"50-201"},{"days":["M","W"],"start":"15:00","end":"17:00","room":"50-201"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.101"},{"code":"21T.102","title":"Voice and Speech for the Actor","level":"U","description":"Thorough exploration of the voice in the context of human communication, provides a progression of exercises designed to free, develop, and strengthen the voice — first as a human instrument and then as the actor's instrument. Explores a progression of voice work that begins with physical awareness and breathing, moving into breath awareness, discovery of the body as the source and amplifier of sound vibration, opens the vocal channel, and develops strength and range in creative expression. Uses historical speeches and heightened language text to expand use and freeing of voice and self. Subject may culminate in a public presentation. Final grade highly dependent on attendance. Students taking graduate version will complete additional assignments. Limited to 20; preference to Theater majors, minors, and concentrators who have pre-registered.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"50-201"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"50-201"},{"days":["T","R"],"start":"15:00","end":"17:00","room":"50-201"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.102"},{"code":"21T.103","title":"Motion Theater","level":"U","description":"Examines the theatrical event from the perspective of composition in a performance workshop. Studio exercises address the process of developing a theatrical work through an internalized understanding of compositional principles in theater. Examines physical action in time and space. Includes outside readings, videos, short essays, and in-class discussions. Provides the performer, director, choreographer, designer or writer opportunities to engage with large and small group ensembles in creation of theatrical events. Topics include image, motion, shape, repetition, gesture, and spatial relationship. Students taking graduate version complete additional assignments. Preference to majors, minors, and concentrators. Admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.103"},{"code":"21T.110","title":"Physical Improvisation: Bodies in Motion","level":"U","description":"Explores the realities of the body in space and motion - interacting with gravity, momentum, inertia, alignment, negative space, one's imagination, one's body, other bodies, the present room and rooms from memory, geometry, stillness, and more. By releasing tension and abandoning the notion of pre-planning, students experience a natural, spontaneous flow of movement, opening themselves up to, and diving into, whatever might happen. Develops alertness in order to work in an energetic state of physical disorientation, self-correcting what doesn't work and reinforcing what does on the spot, discovering physical/emotional truths and shared moments that leave students aware, centered, incredibly present, and sharply alive. Students taking graduate version will complete additional assignments. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"13:00","room":"W97-160"},{"days":["M","W"],"start":"13:00","end":"15:00","room":"W97-162"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"W97-162"},{"days":["T","R"],"start":"15:00","end":"17:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.110"},{"code":"21T.121","title":"Drawing for Designers","level":"U","description":"Explores drawing as a fundamental component of the design process. In-class drawing exercises focus on developing the hand-to-eye relationship and pre-visualization skills essential to any designer. Studies the use drawing as a route to understanding space and form and achieving accuracy through expression. By drawing figures, landscapes and/or still life compositions in a variety of media, students investigate the figure/ground relationship while dealing with tone, line, and composition, which are all requisite elements of design. Provides exposure to designers who have used drawing as a central component of their work. Students create a portfolio that includes in-class drawings, studies done outside of class, and one research-based written project. Lab fee required.  Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"14:00","room":"W97-261"},{"days":["W"],"start":"14:00","end":"17:00","room":"W97-261"},{"days":["R"],"start":"14:00","end":"17:00","room":"W97-261"},{"days":["R"],"start":"19:00","end":"22:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.121"},{"code":"21T.131","title":"Script Analysis","level":"U","description":"Focuses on reading a play's script critically and theatrically, with a view to mounting a coherent production. Through careful, intensive analysis of a variety of plays from different periods and aesthetics, a pattern emerges for discerning what options exist for interpreting a script from the distinct perspectives of the playwright, the actor, the designer, and the director. Students discuss the consequences of those options for production.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"16:00","room":"1-136"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.131"},{"code":"21T.150","title":"Playwriting Fundamentals","level":"U","description":"Introduces the craft of writing for the theater, with special attention to the basics of dramatic structure. Through weekly assignments and in-class exercises, students explore character, conflict, language and plasticity in scenes and short plays. In workshop format, students present individual work for feedback and heavily revise their work based on that response. Readings include a variety of plays.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.150"},{"code":"21T.201","title":"Acting with the Camera","level":"U","description":"Studio workshop explores the discipline of acting for the camera through in-class exercises that focus on the creative challenges inherent to both filming and being filmed. Investigates the performer in the history of cinema, television, and multimedia stage performance through readings, screenings, and experimentation with the theory and practice of performing for and with the camera. Culminates in student-written, edited, directed, and acted short films. Instruction in written and oral communication provided. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.201"},{"code":"21T.202","title":"Solo Performance","level":"U","description":"Students study a range of solo performances, explore their own artistic voices, and hone their individual acting skills. Selected viewings and studio exercises support students with diverse strategies for composing and staging solo work. Culminates with students creating their own original solo performance pieces. Students taking graduate version complete additional assignments. Enrollment limited to 20.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"50-201"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.202"},{"code":"21T.220","title":"Set Design","level":"U","description":"Investigates the creation of set design for live performance. Students develop designs related to current production projects at MIT. Focuses on developing the designer's communication tools, particularly in the areas of visual research, 3-D digital model making, and design presentation. Examines the relationship of set design to theater architecture, emerging media technologies and dramaturgies of the 20th and 21st centuries. In addition to creating their own designs, students research, write about, and present the work and practice of a set designer. Lab fee required.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.220"},{"code":"21T.223","title":"Sound Design","level":"U","description":"Introduces the elements of a sound designer's work, such as music and sound effects which inform and make stage action plausible, to sound system design and placement and the use of microphones. Discusses how effective sound design enhances live performance by clarifying storytelling, heightening emotional experience, and making words and music legible to an audience. Provides students with the tools to continue practicing and appreciating the art regardless of their professional ambitions. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.223"},{"code":"21T.231","title":"Talking and Dancing","level":"U","description":"Interdisciplinary dance theater studio invites students to investigate the spaces between dance and theater. Students engage in an array of acting and dance techniques to generate text from movement and movement from text. In-studio exercises examine the process of melding the expressive languages of words with languages of the body. Students use existing texts and compose original texts in the development of solo, duet, and ensemble projects. Explores the process of seeing and providing peer feedback to further expand the process of revision. Readings, short writings, video viewings, and guest lectures provide multiple avenues of understanding and illumine differing ways of making. Culminates with an opportunity for students to refine, develop, and share their projects in performance. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.231"},{"code":"21T.232","title":"Producing Podcasts","level":"U","description":"Students write and produce a pilot episode of a narrative podcast (about fifteen minutes in length); sources come from interviews or research that students conduct. At the start of the term, students pitch possible stories. Discussions of selected episodes of narrative podcasts such as Serial, Homecoming, and This American Life. Introduces the basics of podcast recording with a primer on using Logic Pro X and hardware like the Apogee Duet. Students record and edit a rough draft of their podcast using provided portable recording studio kits. Podcasts shared with the larger MIT community at the Podcast Listening Room at the end of term. Students taking graduate version complete alternate assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.232"},{"code":"21T.240","title":"Sport as Performance","level":"U","description":"Seminar investigates the aesthetics of sport as theatrical performance and explores the performance of race, gender, class, nation, and sexuality in sport. Readings drawn from theatre/performance studies, anthropology, sociology, ethnic studies, gender studies, history, and kinesiology. Topics include barnstorming, Olympics, Title IX, Native American mascots, and a variety of sports ranging from football to figure skating. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.240"},{"code":"21T.242","title":"Asian American Theater","level":"U","description":"Explores the history and impact of Asian American theater. Readings include plays and materials about cultural and political issues, family, and identity. Includes short formal and creative writing assignments and scene work resulting in a collaborative final performance. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.242"},{"code":"21T.246","title":"Studies in Drama","level":"U","description":"Intensive study of an important topic or period in drama. Close analysis of major plays, enriched by critical readings and attention to historical and theatrical contexts. Instruction and practice in oral and written communication through student presentations and research essays. Previously taught topics include: Renaissance Drama; Shakespeare with his Contemporaries; Oscar Wilde; and Stoppard and Company. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.246"},{"code":"21T.251","title":"Screenwriting","level":"U","description":"Explores the fundamentals of screenplay writing.  Presents skills to create compelling characters and stories in different dramatic genres (comedy, drama). In addition to their own writing, students read a selection of screenplays and watch short films that form the basis of class discussion early in the term.  Class is modeled on a professional development workshop in which participants, over the course of the term, write a short screenplay, including a final draft.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.251"},{"code":"21T.301","title":"Acting Styles","level":"U","description":"Refines the student actor's investigation of languages of the stage, including work on heightened texts and physical presentations. Explores issues of creative expression and embodying character within styles of different theatrical traditions. Time periods and styles studied may differ from term to term and may include an open presentation. Students taking graduate version complete additional assignments. Enrollment limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.301"},{"code":"21T.320","title":"Interactive Design for Live Performance","level":"U","description":"Studies design, history, artistic purposes, and programming techniques involved in the development of interactive performance design systems for controlling video projection, media, and lighting for live performances. Includes readings, viewings of historical and contemporary works, and in class-practice and performance. Students use motion-sensing input devices, such as the Kinect, infrared-light tracking, accelerometers, live video, and generative graphics, to create interactive design systems. Students taking graduate version complete additional assignments.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.320"},{"code":"21T.424","title":"Topics in Performance Studies","level":"U","description":"Multidisciplinary lecture/workshop engages students in a variety of approaches to the study and practice of performance as an area of aesthetic and social interaction. Special attention paid to the use of diverse media in performance. Interdisciplinary approaches to study encourage students to seek out material histories of performance and practice. May be repeated for credit if topics differ.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"16:00","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.424"},{"code":"21T.500","title":"Theater Arts Production","level":"G","description":"No textbook information available","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"W97-160"}]},{"type":"Lab","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.500"},{"code":"21T.501","title":"Acting Styles","level":"G","description":"Refines the student actor's investigation of languages of the stage, including work on heightened texts and physical presentations. Explores issues of creative expression and embodying character within styles of different theatrical traditions. Time periods and styles studied may differ from term to term and may include an open presentation. Students taking graduate version complete additional assignments. Enrollment limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.501"},{"code":"21T.502","title":"Voice and Speech for the Actor","level":"G","description":"Thorough exploration of the voice in the context of human communication, provides a progression of exercises designed to free, develop, and strengthen the voice — first as a human instrument and then as the actor's instrument. Explores a progression of voice work that begins with physical awareness and breathing, moving into breath awareness, discovery of the body as the source and amplifier of sound vibration, opens the vocal channel, and develops strength and range in creative expression. Uses historical speeches and heightened language text to expand use and freeing of voice and self. Subject may culminate in a public presentation. Final grade highly dependent on attendance. Students taking graduate version will complete additional assignments.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"50-201"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"50-201"},{"days":["T","R"],"start":"15:00","end":"17:00","room":"50-201"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.502"},{"code":"21T.503","title":"Motion Theater","level":"G","description":"Examines the theatrical event from the perspective of composition in a performance workshop. Studio exercises address the process of developing a theatrical work through an internalized understanding of compositional principles in theater. Examines physical action in time and space. Includes outside readings, videos, short essays, and in-class discussions. Provides the performer, director, choreographer, designer, or writer opportunities to engage with large and small group ensembles in creation of theatrical events. Topics include image, motion, shape, repetition, gesture, and spatial relationship. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.503"},{"code":"21T.510","title":"Physical Improvisation: Bodies in Motion","level":"G","description":"Explores the realities of the body in space and motion - interacting with gravity, momentum, inertia, alignment, negative space, one's imagination, one's body, other bodies, the present room and rooms from memory, geometry, stillness, and more. By releasing tension and abandoning the notion of pre-planning, students experience a natural, spontaneous flow of movement, opening themselves up to, and diving into, whatever might happen. Develops alertness in order to work in an energetic state of physical disorientation, self-correcting what doesn't work and reinforcing what does on the spot, discovering physical/emotional truths and shared moments that leave students aware, centered, incredibly present, and sharply alive. Students taking graduate version will complete additional assignments. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"13:00","room":"W97-160"},{"days":["M","W"],"start":"13:00","end":"15:00","room":"W97-162"},{"days":["T","R"],"start":"13:00","end":"15:00","room":"W97-162"},{"days":["T","R"],"start":"15:00","end":"17:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.510"},{"code":"21T.523","title":"Sound Design","level":"G","description":"Introduces the elements of a sound designer's work, such as music and sound effects which inform and make stage action plausible, to sound system design and placement and the use of microphones. Discusses how effective sound design enhances live performance by clarifying storytelling, heightening emotional experience, and making words and music legible to an audience. Provides students with the tools to continue practicing and appreciating the art regardless of their professional ambitions. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.523"},{"code":"21T.524","title":"Topics in Performance Studies","level":"G","description":"See description under 21M.846. Assignments differ.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"16:00","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.524"},{"code":"21T.532","title":"Producing Podcasts","level":"G","description":"Students write and produce a pilot episode of a narrative podcast (about fifteen minutes in length); sources come from interviews or research that students conduct. At the start of the term, students pitch possible stories. Discussions of selected episodes of narrative podcasts such as Serial, Homecoming, and This American Life. Introduces the basics of podcast recording with a primer on using Logic Pro X and hardware like the Apogee Duet. Students record and edit a rough draft of their podcast using provided portable recording studio kits. Podcasts shared with the larger MIT community at the Podcast Listening Room at the end of term. Students taking graduate version complete alternate assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W97-261"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.532"},{"code":"21T.601","title":"Acting with the Camera","level":"G","description":"Studio workshop explores the discipline of acting for the camera through in-class exercises that focus on the creative challenges inherent to both filming and being filmed. Investigates the performer in the history of cinema, television, and multimedia stage performance through readings, screenings, and experimentation with the theory and practice of performing for and with the camera. Culminates in student-written, edited, directed, and acted short films. Instruction in written and oral communication provided. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"13:00","room":"W97-160"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.601"},{"code":"21T.602","title":"Solo Performance","level":"G","description":"Students study a range of solo performances, explore their own artistic voices, and hone their individual acting skills. Selected viewings and studio exercises support students with diverse strategies for composing and staging solo work. Culminates with students creating their own original solo performance pieces. Students taking graduate version complete additional assignments. Enrollment limited to 20.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"50-201"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.602"},{"code":"21T.610","title":"Choreography: Making Dances","level":"G","description":"Laboratory-style class explores and invents techniques used to create dances. Students practice techniques focused on how and where to begin making a dance — sampling some of the endless ways to start a process, such as from the body, an idea, text, or a song — and then how to build up from there. Students make dances that are more than just a collection of moves, but events that do something, say something, or ask something. Builds a clear understanding of how a dance has an arc, a clear beginning, middle, and end, so that by doing it or watching it, both participants and audience end up somewhere new. Develops an understating of, and facility with, a wide variety of topics used to explore, start, and generate movement, dance, and performative events involving bodies moving through space. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"13:00","room":"W97-162"}]}],"url":"http://student.mit.edu/catalog/m21Ta.html#21T.610"},{"code":"21W.011","title":"Writing and Rhetoric: Rhetoric and Contemporary Issues","level":"U","description":"Discusses rhetorical strategies that aim to increase public awareness of social and ethical issues and persuade readers of the value of particular positions or solutions. Explores perspectives on a range of issues including: poverty, homelessness, mental illness, racial and gender inequality, the politics of food, civic responsibility, and the role of mass media in society. Students analyze various classic and contemporary texts as well as the visual rhetoric of documentary photographs and films. Students also write personal essays, research papers, and grant proposals on topics of their choice. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"8-119"},{"days":["T","R"],"start":"19:00","end":"20:30","room":"8-119"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.011"},{"code":"21W.012","title":"Writing and Rhetoric: Food for Thought","level":"U","description":"Explores social and ethical issues (e.g., nutrition, sustainability, and justice) that surround food as both material fact and personal and cultural symbol. Assignments include a food memoir and a policy argument for MIT Dining, and involve brainstorming, drafting, peer review, and revision. Students learn rhetorical strategies for analyzing written and visual texts, developing persuasive arguments, and synthesizing information from primary sources. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"E17-136"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.012"},{"code":"21W.013","title":"Writing and Rhetoric: Introduction to Contemporary Rhetoric","level":"U","description":"Considers how rhetoric shapes current events in politics, science, and society. Students study rhetoric as a theoretical framework for developing persuasive arguments, as a method of analyzing written, oral, and visual texts, and as a mode of human inquiry. Assignments include analytical, persuasive, and research-based essays, as well as oral presentations, group discussions, and debates. Readings drawn from political speeches, scientific arguments, and popular media. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.013"},{"code":"21W.016","title":"Writing and Rhetoric: Community and Change in the World","level":"U","description":"Explores how communication and applied rhetoric can be used to make persuasive arguments, engage community, and effect change. Students identify and research social, institutional, and environmental issues that matter to them, define specific problems, and propose solutions. Past projects have addressed food waste on campus, public transit in rural areas, student-athlete mental health, the electoral college, and more. Provides instruction in analyzing written, spoken, and visual texts; researching meaningful topics; public speaking; understanding rhetorical concepts and deploying them effectively; and drafting and revising policy proposals. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.016"},{"code":"21W.021","title":"Writing and Experience: MIT Inside, Live","level":"U","description":"Acting as participant-observers, students investigate MIT's history and culture through visiting the Institute's archives and the MIT Museum and evaluating depictions of MIT in popular culture. Students hone narrative and argumentative skills, working collaboratively and individually to examine inflection points in Institute history. Presents strategies for constructing arguments and presentations, culminating in a public slideshow on a historical aspect of student life at MIT. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.021"},{"code":"21W.022","title":"Writing and Experience: Reading and Writing Autobiography","level":"U","description":"Explores how writers establish their voice and use the story and essay forms to telegraph consciousness, lived experience, the historical moment, and a sense of place. Investigates various modes of writing (narrative, analytical, investigative, argumentative) and their suitability for different purposes and audiences. Drawing from a range of autobiographical writing as examples to analyze, students write essays about their experiences and the interaction of self and society. Emphasizes clarity, specificity, and structure. Features opportunities for students to improve their oral communication skills through class discussion, oral presentations, and peer review workshops. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.022"},{"code":"21W.023","title":"Writing and Experience: Autobiography and Society","level":"U","description":"Draws on a range of autobiographical writing, including hybrid first-person genres, such as food, travel, and nature memoirs, as examples for students to analyze. Students write essays about their life experiences with careful attention to authenticity, precision, and the expectations of their audiences. Specific attention is given to the social contexts and utility of the different genres of life writing. Aims to build students' confidence in their oral communication skills through frequent class discussions, peer review, and a sustained book review and research project with final oral presentation. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E17-136"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.023"},{"code":"21W.024","title":"Writing and Experience: Autobiographical Storytelling","level":"U","description":"Drawing from a range of autobiographical writing as examples to analyze, students compose original work including a writing portfolio and collaborative multimedia project like a zine, podcast, or comic. Emphasizes clarity, specificity, and structure; investigates various modes of writing (narrative, analytical, expository) and their suitability for different purposes. Readings focus on memory and imagination, the multiplicity of identity, development of voice, and creation of story from experience through reflection and revision. In-class activities include discussion, freewriting, and workshops. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"E17-136"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.024"},{"code":"21W.031","title":"Science Writing and New Media: Explorations in Communicating about Science and Technology","level":"U","description":"Examines principles of good writing, focusing on those associated with scientific and technical writing. Considers the effects of new media as an avenue for communicating about science. Students discuss scientific articles and essays and work in small groups to critique each other's writing. Assignments include a critical review, a science essay for the general public, and a research or service project proposal. Students choose topics that reflect their background and interests. Formal and informal presentations and group discussions develop oral communication skills. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"E17-136"},{"days":["T","R"],"start":"15:00","end":"16:30","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.031"},{"code":"21W.035","title":"Science Writing and New Media: Elements of Science Writing for the Public","level":"U","description":"Introduces ways of communicating scientific information meaningfully to public audiences, and teaches features that distinguish science writing for the public from scientific writing aimed at experts. Discussions analyze various forms of popular science communication to identify rhetorical strategies that engage and educate readers of varying backgrounds and identities. Students write about topics they are genuinely interested in related to science, medicine, technology, and/or engineering. Assignments incorporate primary and secondary background research, drafting, presentations, peer review, and revision. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"56-180"},{"days":["M","W"],"start":"14:00","end":"15:30","room":"56-180"},{"days":["T","R"],"start":"11:00","end":"12:30","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.035"},{"code":"21W.051","title":"Emotional Intelligence and Team Communication","level":"U","description":"Examines the role of emotional intelligence in both our individual lives and our collaborations. Considers a broad range of topics and communication strategies, including self-awareness, listening, trust, habit formation, conflict, negotiation, and constructive dialogue. High-quality writing and video presentations serve as the focus for the class discussion and as models for student essays and presentations. Students produce both individual and collaborative work. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.051"},{"code":"21W.219","title":"Foundations of Academic and Professional Writing (ELS)","level":"G","description":"For high-intermediate bilingual students who wish or need to improve accuracy, structure, style, and word choice in their academic and professional writing. Through short weekly writing assignments such as problem-solution texts, process descriptions, and data commentaries, students practice accurate grammar and punctuation, effective sentence and paragraph structure, and appropriate word choice, with extensive revisions. Discusses the use of generative AI in writing and learning. Students are encouraged to use their own research and other coursework for writing assignments. May be repeated for credit with permission of instructor. Undergraduates by placement only. No listeners. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.219"},{"code":"21W.220","title":"Foundations of Academic and Professional Writing (ELS)","level":"U","description":"For high-intermediate bilingual students who wish or need to improve accuracy, structure, style, and word choice in their academic and professional writing. Through short weekly writing assignments such as problem-solution texts, process descriptions, and data commentaries, students practice accurate grammar and punctuation, effective sentence and paragraph structure, and appropriate word choice, with extensive revisions. Discusses the use of generative AI in writing and learning. Students are encouraged to use their own research and other coursework for writing assignments. May be repeated for credit with permission of instructor. No listeners. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.220"},{"code":"21W.222","title":"Expository Writing for Bilingual Students","level":"U","description":"Focuses on the skills necessary for bilingual students to write successful academic papers in English. Reviews key principles of American rhetoric and academic writing style with attention to accurate grammar and vocabulary usage. Teaches clear development, organization, and presentation of ideas as well as effective outside research and citation. Utilizes analysis of professional and student writing to generate discussion and understand the most effective ways to communicate. Frequent critique and revision. Discusses the use of generative AI in writing and learning. Assignments include three papers and an oral project. May be repeated for credit with permission of instructor. Limited to 15; undergraduates only.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"66-154"},{"days":["T","R"],"start":"15:30","end":"17:00","room":"1-135"},{"days":["T","R"],"start":"15:30","end":"17:00","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.222"}]);
